def _apply_cuts_skip_reason(cut):
    """Why a CutList entry is not applicable by apply_cuts, or None if it is."""
    if not isinstance(cut, dict):
        return "not an object"
    if cut.get("action") not in ("lift", "ripple_delete"):
        return f"action {cut.get('action')!r} is not lift or ripple_delete"
    span = cut.get("span")
    if not isinstance(span, dict):
        return "missing span"
    if span.get("start") is None or span.get("end") is None:
        return "span missing start/end"
    return None

def _strata_clip_ref(p: Dict[str, Any]) -> Any:
    """The clip ref from any accepted alias — one place, so aliases can't drift
    between action handlers."""
    for key in _STRATA_CLIP_REF_KEYS:
        value = p.get(key)
        if value:
            return value
    return None

def _edit_engine_collect_items(tl, *, track_index: Optional[int] = None) -> List[Dict[str, Any]]:
    """Serialize video timeline items with the source mapping the planner needs."""
    rows: List[Dict[str, Any]] = []
    track_count = int(tl.GetTrackCount("video") or 0)
    indices = [int(track_index)] if track_index else range(1, track_count + 1)
    for index in indices:
        try:
            items = tl.GetItemListInTrack("video", index) or []
        except Exception:
            continue
        for item in items:
            try:
                row: Dict[str, Any] = {
                    "track_index": index,
                    "item_name": item.GetName(),
                    "timeline_start_frame": _frame_int(item.GetStart()),
                    "timeline_end_frame": _frame_int(item.GetEnd()),
                }
            except Exception:
                continue
            source_start = None
            if _has_method(item, "GetSourceStartFrame"):
                try:
                    source_start = _frame_int(item.GetSourceStartFrame())
                except Exception:
                    source_start = None
            if source_start is None and _has_method(item, "GetLeftOffset"):
                try:
                    source_start = _frame_int(item.GetLeftOffset())
                except Exception:
                    source_start = None
            row["source_start_frame"] = source_start or 0
            try:
                mpi = item.GetMediaPoolItem()
                if mpi is not None:
                    row["media_ref"] = mpi.GetUniqueId()
                    try:
                        row["media_path"] = mpi.GetClipProperty("File Path")
                    except Exception:
                        pass
            except Exception:
                pass
            # Linked audio track indices so the planner can mirror kept ranges
            # onto sound (see #67 — tighten variants were coming out silent).
            try:
                audio_indices, _audio_note = _edit_engine_linked_audio_tracks(
                    tl, item, row["timeline_start_frame"], row["timeline_end_frame"]
                )
                row["audio_track_indices"] = audio_indices
            except Exception:
                row["audio_track_indices"] = []
            rows.append(row)
    return rows

def _edit_engine_timeline_fps(tl) -> float:
    try:
        fps = float(tl.GetSetting("timelineFrameRate") or 0)
        return fps if fps > 0 else 24.0
    except Exception:
        return 24.0

def _edit_engine_capture(tl) -> Dict[str, Any]:
    """Duration/clip-count readback for execute results."""
    out: Dict[str, Any] = {}
    try:
        out["duration_seconds"] = _brain_edits.capture_metric(_brain_edits.METRIC_DURATION_SECONDS, tl)
        out["clip_count"] = _brain_edits.capture_metric(_brain_edits.METRIC_CLIP_COUNT, tl)
    except Exception:
        pass
    return out

def _edit_engine_track_counts(tl) -> Dict[str, int]:
    """Per-track-type item counts — the swap symmetry signal in readback."""
    counts: Dict[str, int] = {}
    for tt in ("video", "audio"):
        total = 0
        try:
            n = int(tl.GetTrackCount(tt) or 0)
        except Exception:
            n = 0
        for ti in range(1, n + 1):
            try:
                total += len(tl.GetItemListInTrack(tt, ti) or [])
            except Exception:
                continue
        counts[tt] = total
    return counts

def _edit_engine_find_slot_item(tl, track_index: int, slot_start: int, slot_end: int):
    """The video item occupying exactly [slot_start, slot_end] on a track."""
    try:
        for cand in (tl.GetItemListInTrack("video", int(track_index)) or []):
            if _frame_int(cand.GetStart()) == slot_start and _frame_int(cand.GetEnd()) == slot_end:
                return cand
    except Exception:
        pass
    return None

def _edit_engine_linked_audio_tracks(
    tl, target_item, slot_start: int, slot_end: int,
) -> Tuple[List[int], str]:
    """Audio track indices carrying the target item's linked audio.

    Prefers GetLinkedItems; falls back to matching slot-overlapping audio
    items that share the target's media-pool source. ([], note) when there is
    no linked audio (audio-only handling stays untouched) or no target item.
    """
    if target_item is None:
        return [], "target video item not found on its track; audio left untouched"
    linked_ids: set = set()
    get_linked = getattr(target_item, "GetLinkedItems", None)
    if callable(get_linked):
        try:
            for linked_item in (get_linked() or []):
                uid = getattr(linked_item, "GetUniqueId", None)
                if callable(uid):
                    linked_ids.add(str(uid()))
        except Exception:
            linked_ids = set()
    target_media_id = None
    try:
        mpi = target_item.GetMediaPoolItem()
        if mpi is not None:
            target_media_id = str(mpi.GetUniqueId())
    except Exception:
        target_media_id = None
    if not linked_ids and not target_media_id:
        return [], "GetLinkedItems unavailable and no media id to match; audio left untouched"

    indices: List[int] = []
    try:
        audio_tracks = int(tl.GetTrackCount("audio") or 0)
    except Exception:
        audio_tracks = 0
    for ti in range(1, audio_tracks + 1):
        try:
            items = tl.GetItemListInTrack("audio", ti) or []
        except Exception:
            continue
        for cand in items:
            try:
                c_start = _frame_int(cand.GetStart())
                c_end = _frame_int(cand.GetEnd())
            except Exception:
                continue
            if c_start is None or c_end is None or c_start >= slot_end or c_end <= slot_start:
                continue
            is_linked = False
            if linked_ids:
                uid = getattr(cand, "GetUniqueId", None)
                if callable(uid):
                    try:
                        is_linked = str(uid()) in linked_ids
                    except Exception:
                        is_linked = False
            if not is_linked and target_media_id:
                try:
                    c_mpi = cand.GetMediaPoolItem()
                    is_linked = c_mpi is not None and str(c_mpi.GetUniqueId()) == target_media_id
                except Exception:
                    is_linked = False
            if is_linked and ti not in indices:
                indices.append(ti)
    if not indices:
        return [], "no linked audio found for the target item"
    return indices, ""

@mcp.tool()
@_destructive_op("edit_engine")
@_missing_param_envelope
def edit_engine(action: str, params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Evidence-driven edit loops (Phase E): selects assembly, tighten, swap.

    Every loop is plan → confirm → execute. plan_* actions are dry-run by
    construction: they query the DB-canonical analysis store and return a
    per-decision rationale plus a stored plan_id. execute_* actions require a
    confirm_token, run under the version-on-mutate hook (the timeline is
    archived first), and return before/after metrics as readback.

    Actions:
    - plan_selects(min_select_potential?, max_duration_seconds?, timeline_name?,
      max_shots?, handle_seconds?, analysis_root?) — rank shots by deep-tier
      select potential (clip-level fallback), story-spine order. Additive.
    - execute_selects(plan_id, confirm_token?) — creates a NEW selects timeline
      from the plan's clip in/out ranges. Nothing existing is touched.
    - plan_tighten(timeline_name?, target_ratio?, min_pause_seconds?,
      handle_seconds?, include_audio?) — dead-air lifts from transcript-gap
      evidence for the current (or named) timeline. Kept ranges mirror onto the
      items' linked audio tracks by default so the variant is audible; pass
      include_audio=false for a video-only (silent) assembly.
    - execute_tighten(plan_id, confirm_token?, include_details?) — assembles a
      tightened VARIANT timeline from the plan's keep ranges (video + mirrored
      audio), never mutating the original. Readback includes an audio_accounting
      block and a compact structural_diff (counts + a small sample); the full
      per-item diff is persisted in the plan record (get_plan → execution_summary)
      and returned inline only when include_details=true.
    - plan_swap(track_index?, timeline_start_frame | item_name, kind?, limit?)
      — alternates for one timeline item via the similarity index.
    - execute_swap(plan_id, alternate_index, confirm_token?) — replaces the
      item in place (lift + positioned append, same slot) on the current
      timeline (version-archived first).
    - list_plans(limit?) / get_plan(plan_id)
    """
    from src.domains.timeline_edit.actions import _build_append_clip_info_dict, _timeline_create_variant_from_ranges, _timeline_lift_range_impl
    from src.domains.media_pool_ingest.actions import _compact_structural_diff
    p = _tool_params(params)

    def _project_context(*, need_resolve: bool) -> Tuple[Optional[Any], Optional[Any], Optional[str], Optional[Dict[str, Any]]]:
        # An explicit analysis_root always wins — the evidence DB the caller
        # analyzed into may differ from the provider's derived root (e.g. a
        # headless analysis keyed by project name only).
        analysis_root = p.get("analysis_root") or p.get("analysisRoot")
        explicit_root = str(analysis_root) if analysis_root and os.path.isdir(str(analysis_root)) else None
        vctx = _destructive_versioning_provider()
        if vctx is not None:
            r, proj, project_root, _name = vctx
            return r, proj, explicit_root or project_root, None
        if not need_resolve and explicit_root:
            return None, None, explicit_root, None
        return None, None, None, _err(
            "No project context — open a Resolve project (or pass analysis_root for plan_selects)."
        )

    if action == "list_plans":
        _r, _proj, project_root, err = _project_context(need_resolve=False)
        if err:
            return err
        return _edit_engine_mod.list_plans(project_root, limit=int(p.get("limit") or 20))

    if action == "get_plan":
        _r, _proj, project_root, err = _project_context(need_resolve=False)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, str(p.get("plan_id") or p.get("planId") or ""))
        if not plan:
            return _err("plan not found")
        if plan.get("_corrupt"):
            return _err("plan file failed its fingerprint check — re-plan")
        return {"success": True, "plan": plan}

    if action == "plan_selects":
        _r, _proj, project_root, err = _project_context(need_resolve=False)
        if err:
            return err
        return _edit_engine_mod.plan_selects(
            project_root,
            timeline_name=p.get("timeline_name") or p.get("timelineName"),
            max_duration_seconds=p.get("max_duration_seconds") or p.get("maxDurationSeconds"),
            min_select_potential=str(p.get("min_select_potential") or p.get("minSelectPotential") or "medium"),
            handle_seconds=float(p.get("handle_seconds") or p.get("handleSeconds") or _edit_engine_mod.DEFAULT_HANDLE_SECONDS),
            max_shots=int(p.get("max_shots") or p.get("maxShots") or 60),
        )

    if action == "plan_tighten":
        _r, proj, project_root, err = _project_context(need_resolve=True)
        if err:
            return err
        tl = (_find_timeline_by_name(proj, p.get("timeline_name") or p.get("timelineName"))[0] if (p.get("timeline_name") or p.get("timelineName")) else proj.GetCurrentTimeline())
        if not tl:
            return _err("Timeline not found")
        items = _edit_engine_collect_items(tl, track_index=p.get("track_index") or p.get("trackIndex"))
        return _edit_engine_mod.plan_tighten(
            project_root,
            items=items,
            timeline_name=tl.GetName(),
            timeline_fps=_edit_engine_timeline_fps(tl),
            target_ratio=p.get("target_ratio") or p.get("targetRatio"),
            min_pause_seconds=float(p.get("min_pause_seconds") or p.get("minPauseSeconds") or _edit_engine_mod.DEFAULT_MIN_PAUSE_SECONDS),
            handle_seconds=float(p.get("handle_seconds") or p.get("handleSeconds") or _edit_engine_mod.DEFAULT_HANDLE_SECONDS),
            include_audio=str(p.get("include_audio", p.get("includeAudio", True))).strip().lower() not in {"false", "0", "no", "none", "off"},
        )

    if action == "plan_swap":
        _r, proj, project_root, err = _project_context(need_resolve=True)
        if err:
            return err
        tl = (_find_timeline_by_name(proj, p.get("timeline_name") or p.get("timelineName"))[0] if (p.get("timeline_name") or p.get("timelineName")) else proj.GetCurrentTimeline())
        if not tl:
            return _err("Timeline not found")
        items = _edit_engine_collect_items(tl, track_index=p.get("track_index") or p.get("trackIndex"))
        target = None
        wanted_start = p.get("timeline_start_frame") if p.get("timeline_start_frame") is not None else p.get("timelineStartFrame")
        wanted_name = p.get("item_name") or p.get("itemName")
        for row in items:
            if wanted_start is not None and int(row["timeline_start_frame"]) == int(wanted_start):
                target = row
                break
            if wanted_name and row.get("item_name") == wanted_name:
                target = row
                break
        if target is None:
            return _err(
                "Target item not found — pass timeline_start_frame or item_name "
                f"(items: {[{'name': r.get('item_name'), 'start': r['timeline_start_frame']} for r in items[:20]]})"
            )
        return _edit_engine_mod.plan_swap(
            project_root,
            item=target,
            timeline_name=tl.GetName(),
            timeline_fps=_edit_engine_timeline_fps(tl),
            kind=str(p.get("kind") or "visual"),
            limit=int(p.get("limit") or 5),
        )

    if action == "execute_selects":
        _r, proj, project_root, err = _project_context(need_resolve=True)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, str(p.get("plan_id") or p.get("planId") or ""))
        if not plan or plan.get("_corrupt"):
            return _err("plan not found (or failed its fingerprint check) — re-plan")
        if plan.get("kind") != "selects":
            return _err(f"plan {plan.get('plan_id')} is a {plan.get('kind')} plan")
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            return _issue_confirm_token(
                action="edit_engine.execute_selects", params=p,
                preview={
                    "operation": "edit_engine.execute_selects",
                    "warning": "Creates a NEW selects timeline; no existing timeline is modified.",
                    "timeline_name": plan.get("timeline_name"),
                    "decision_count": len(plan.get("decisions") or []),
                    "estimated_duration_seconds": plan.get("estimated_duration_seconds"),
                },
            )
        blocked = _consume_confirm_token(action="edit_engine.execute_selects", params=p)
        if blocked:
            return blocked
        mp = proj.GetMediaPool()
        if not mp:
            return _err("No media pool")
        root_folder = mp.GetRootFolder()
        name = str(plan.get("timeline_name") or "Selects")
        if _find_timeline_by_name(proj, name)[0]:
            name = f"{name} {time.strftime('%H%M%S')}"
        tl = mp.CreateEmptyTimeline(name)
        if not tl:
            return _err("Failed to create selects timeline")
        # #113 Tier 1: AppendToTimeline below targets Resolve's CURRENT timeline
        # implicitly, so a silently-failed switch appends onto whatever was
        # current instead — into the user's own timeline. Refuse rather than
        # build the selects somewhere unintended.
        if not _set_current_timeline(proj, tl):
            return _err(f"Created selects timeline '{name}' but could not make it current; "
                        "refusing to append, which would target the wrong timeline")
        timeline_start = _timeline_start_frame(tl)
        built = []
        build_errors = []
        record_cursor = 0
        for i, ci in enumerate(plan.get("clip_infos") or []):
            append_ci = dict(ci)
            # Sequential assembly: each select lands after the previous one.
            append_ci.setdefault("record_frame", record_cursor)
            append_ci.setdefault("track_index", 1)
            row, row_err = _build_append_clip_info_dict(root_folder, append_ci, i, timeline_start)
            if row_err:
                build_errors.append({"index": i, "error": row_err.get("error")})
                continue
            built.append(row)
            # AppendToTimeline endFrame is exclusive: the item occupies
            # (end - start) frames. Advancing by +1 more leaves a 1-frame gap
            # (black flash) between consecutive selects. See api_truth endFrame entry.
            record_cursor += int(append_ci.get("end_frame", 0)) - int(append_ci.get("start_frame", 0))
        appended = mp.AppendToTimeline(built) if built else None
        readback = _edit_engine_capture(tl)
        # A diff against a source timeline is meaningless for a fresh assembly;
        # a usage-snapshot summary is the structural readback that fits.
        try:
            usage = _timeline_versioning.capture_timeline_clip_usage(tl)
            by_type: Dict[str, int] = {}
            for usage_row in usage:
                by_type[usage_row["track_type"]] = by_type.get(usage_row["track_type"], 0) + 1
            readback["usage_summary"] = {"items": len(usage), "by_track_type": by_type}
        except Exception:
            pass
        run_id = _analysis_runs.current_run_id()
        try:
            _brain_edits.log_brain_edit(
                project_root=project_root,
                analysis_run_id=run_id or "edit-engine",
                edit_type="edit_engine.selects_result",
                tool_name="edit_engine",
                action_name="execute_selects",
                timeline_after=tl.GetName(),
                target_metric=_brain_edits.METRIC_CLIP_COUNT,
                metric_direction="target_value",
                after_value=readback.get("clip_count"),
                rationale=plan.get("summary"),
                params={"plan_id": plan.get("plan_id")},
                result_summary={"appended": len(built), "build_errors": build_errors},
            )
        except Exception:
            pass
        _edit_engine_mod.mark_plan_executed(project_root, plan["plan_id"], {
            "timeline_name": tl.GetName(),
            "appended": len(built),
            "build_errors": build_errors,
            **readback,
        })
        return {
            "success": bool(appended),
            "timeline_name": tl.GetName(),
            "appended": len(built),
            "build_errors": build_errors,
            "readback": readback,
            "plan_id": plan.get("plan_id"),
        }

    if action == "execute_tighten":
        _r, proj, project_root, err = _project_context(need_resolve=True)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, str(p.get("plan_id") or p.get("planId") or ""))
        if not plan or plan.get("_corrupt"):
            return _err("plan not found (or failed its fingerprint check) — re-plan")
        if plan.get("kind") != "tighten":
            return _err(f"plan {plan.get('plan_id')} is a {plan.get('kind')} plan")
        lifts = plan.get("lifts") or []
        keep_ranges = plan.get("keep_ranges") or []
        if not keep_ranges:
            return _err("plan has no keep_ranges — re-plan with this version")
        audio_keep_ranges = sum(1 for r in keep_ranges if str(r.get("track_type", "video")).lower() == "audio")
        video_keep_ranges = len(keep_ranges) - audio_keep_ranges
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            return _issue_confirm_token(
                action="edit_engine.execute_tighten", params=p,
                preview={
                    "operation": "edit_engine.execute_tighten",
                    "warning": (
                        "Assembles a tightened VARIANT timeline from the plan's keep "
                        "ranges; the original timeline is not modified."
                    ),
                    "timeline_name": plan.get("timeline_name"),
                    "lift_count": len(lifts),
                    "keep_range_count": len(keep_ranges),
                    "video_keep_range_count": video_keep_ranges,
                    "audio_keep_range_count": audio_keep_ranges,
                    "audio_note": (
                        f"Variant carries audio ({audio_keep_ranges} audio ranges mirror the video cuts)."
                        if audio_keep_ranges
                        else "WARNING: variant is VIDEO-ONLY (silent) — plan has no audio ranges."
                    ),
                    "estimated_removed_seconds": sum(lift.get("duration_seconds") or 0 for lift in lifts),
                },
            )
        blocked = _consume_confirm_token(action="edit_engine.execute_tighten", params=p)
        if blocked:
            return blocked
        source_tl, _src_index = _find_timeline_by_name(proj, plan.get("timeline_name"))
        if not source_tl:
            return _err(f"Timeline '{plan.get('timeline_name')}' not found")
        before = _edit_engine_capture(source_tl)
        variant_name = f"{plan.get('timeline_name')} — tightened {time.strftime('%H%M%S')}"
        variant = _timeline_create_variant_from_ranges(proj, source_tl, {
            "ranges": keep_ranges,
            "name": variant_name,
        })
        if not variant.get("success"):
            return {"success": False, "error": f"variant assembly failed: {variant.get('error')}", "variant": variant}
        new_tl, _new_index = _find_timeline_by_name(proj, variant.get("name") or variant_name)
        after = _edit_engine_capture(new_tl) if new_tl else {}
        # Cross-name structural diff (source vs variant): trustworthy readback
        # without archived version rows — variants are new-name timelines.
        structural_diff = None
        if new_tl is not None:
            try:
                structural_diff = _timeline_versioning.compare_usage_snapshots(
                    _timeline_versioning.capture_timeline_clip_usage(source_tl),
                    _timeline_versioning.capture_timeline_clip_usage(new_tl),
                )
            except Exception as diff_exc:
                structural_diff = {"error": f"{type(diff_exc).__name__}: {diff_exc}"}
        run_id = _analysis_runs.current_run_id()
        try:
            _brain_edits.log_brain_edit(
                project_root=project_root,
                analysis_run_id=run_id or "edit-engine",
                edit_type="edit_engine.tighten_result",
                tool_name="edit_engine",
                action_name="execute_tighten",
                timeline_before=plan.get("timeline_name"),
                timeline_after=variant.get("name") or variant_name,
                target_metric=_brain_edits.METRIC_DURATION_SECONDS,
                metric_direction="decrease",
                before_value=before.get("duration_seconds"),
                after_value=after.get("duration_seconds"),
                rationale=plan.get("summary"),
                params={"plan_id": plan.get("plan_id")},
                result_summary={"keep_ranges": len(keep_ranges), "lifts": len(lifts)},
            )
        except Exception:
            pass
        # The full per-item structural diff is persisted in the plan record so it
        # stays retrievable (edit_engine get_plan) without bloating every
        # response — see issue #84. The MCP response carries a compact form by
        # default and the full diff only when include_details=true.
        include_details = _media_analysis_bool(
            p.get("include_details", p.get("includeDetails")), False
        )
        _edit_engine_mod.mark_plan_executed(project_root, plan["plan_id"], {
            "variant_timeline": variant.get("name") or variant_name,
            "keep_ranges": len(keep_ranges),
            "lifts": len(lifts),
            "before": before,
            "after": after,
            "structural_diff": structural_diff,
        })
        return {
            "success": True,
            "original_timeline": plan.get("timeline_name"),
            "variant_timeline": variant.get("name") or variant_name,
            "lifts_applied": len(lifts),
            "keep_ranges": len(keep_ranges),
            "lift_rationales": [
                {"lift": [lift["timeline_start_frame"], lift["timeline_end_frame"]], "rationale": lift.get("rationale")}
                for lift in lifts
            ],
            "readback": {
                "before": before,
                "after": after,
                "removed_seconds": (
                    round(before["duration_seconds"] - after["duration_seconds"], 2)
                    if before.get("duration_seconds") is not None and after.get("duration_seconds") is not None
                    else None
                ),
                "structural_diff": (
                    structural_diff if include_details
                    else _compact_structural_diff(structural_diff)
                ),
                "audio_accounting": {
                    "planned_audio_ranges": audio_keep_ranges,
                    "planned_video_ranges": video_keep_ranges,
                    # variant_* count placed items; variant["audio"] counts requested ranges.
                    "variant_audio_items": sum(
                        1 for it in (variant.get("items") or [])
                        if (it.get("range") or {}).get("media_type") == 2
                    ),
                    "variant_video_items": sum(
                        1 for it in (variant.get("items") or [])
                        if (it.get("range") or {}).get("media_type") == 1
                    ),
                    "note": (
                        "Variant carries audio mirrored from the video cuts."
                        if audio_keep_ranges
                        else "Variant is VIDEO-ONLY (silent) — re-plan with include_audio=True for sound."
                    ),
                },
            },
            "plan_id": plan.get("plan_id"),
        }

    if action == "execute_swap":
        _r, proj, project_root, err = _project_context(need_resolve=True)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, str(p.get("plan_id") or p.get("planId") or ""))
        if not plan or plan.get("_corrupt"):
            return _err("plan not found (or failed its fingerprint check) — re-plan")
        if plan.get("kind") != "swap":
            return _err(f"plan {plan.get('plan_id')} is a {plan.get('kind')} plan")
        alternates = plan.get("alternates") or []
        try:
            alt_index = int(p.get("alternate_index") if p.get("alternate_index") is not None else p.get("alternateIndex"))
        except (TypeError, ValueError):
            return _err(f"execute_swap requires alternate_index (0-{len(alternates) - 1})")
        if not (0 <= alt_index < len(alternates)):
            return _err(f"alternate_index out of range (0-{len(alternates) - 1})")
        alternate = alternates[alt_index]
        item_block = plan.get("item") or {}
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            return _issue_confirm_token(
                action="edit_engine.execute_swap", params=p,
                preview={
                    "operation": "edit_engine.execute_swap",
                    "warning": (
                        "Replaces one timeline item in place (lift + positioned append). "
                        "A timeline version is archived first."
                    ),
                    "timeline_name": plan.get("timeline_name"),
                    "slot": [item_block.get("timeline_start_frame"), item_block.get("timeline_end_frame")],
                    "replacement": {
                        "clip_name": alternate.get("clip_name"),
                        "shot_index": alternate.get("shot_index"),
                        "score": alternate.get("score"),
                    },
                },
            )
        blocked = _consume_confirm_token(action="edit_engine.execute_swap", params=p)
        if blocked:
            return blocked
        tl, _tl_index = _find_timeline_by_name(proj, plan.get("timeline_name"))
        if not tl:
            return _err(f"Timeline '{plan.get('timeline_name')}' not found")
        # #113 Tier 1: the swap mutates the current timeline; a failed switch
        # would apply it to whichever timeline happened to be current.
        if not _set_current_timeline(proj, tl):
            return _err(f"Could not make timeline '{plan.get('timeline_name')}' current; "
                        "refusing to swap, which would mutate the wrong timeline")
        before = _edit_engine_capture(tl)
        before["track_counts"] = _edit_engine_track_counts(tl)
        slot_start = int(item_block.get("timeline_start_frame"))
        slot_end = int(item_block.get("timeline_end_frame"))
        target_track = int(item_block.get("track_index") or 1)
        # Capture the target's linked audio BEFORE the lift so the audio lift
        # is scoped to exactly those tracks (the replacement appends linked
        # video+audio, so both sides of the swap stay symmetric).
        target_item = _edit_engine_find_slot_item(tl, target_track, slot_start, slot_end)
        linked_audio_indices, audio_note = _edit_engine_linked_audio_tracks(
            tl, target_item, slot_start, slot_end,
        )
        lift = _timeline_lift_range_impl(tl, {
            "start_frame": slot_start,
            "end_frame": slot_end,
            "track_types": ["video"],
            "track_indices": [target_track],
            "allow_partial_item_delete": True,
            "ripple": False,
        })
        if not lift.get("success"):
            return {"success": False, "error": f"lift failed: {lift.get('error')}", "lift": lift}
        audio_lift = None
        if linked_audio_indices:
            audio_lift = _timeline_lift_range_impl(tl, {
                "start_frame": slot_start,
                "end_frame": slot_end,
                "track_types": ["audio"],
                "track_indices": linked_audio_indices,
                "allow_partial_item_delete": True,
                "ripple": False,
            })
            if not audio_lift.get("success"):
                return {
                    "success": False,
                    "error": f"linked-audio lift failed: {audio_lift.get('error')}",
                    "lift": lift,
                    "audio_lift": audio_lift,
                }
        mp = proj.GetMediaPool()
        root_folder = mp.GetRootFolder()
        timeline_start = _timeline_start_frame(tl)
        frame_range = alternate.get("source_frame_range") or [0, 0]
        ci = {
            "clip_id": alternate.get("resolve_clip_id"),
            "start_frame": int(frame_range[0]),
            "end_frame": int(frame_range[1]),
            # Item starts come from item.GetStart() — absolute timeline frames.
            "record_frame": int(item_block.get("timeline_start_frame")),
            "record_frame_mode": "absolute",
            "track_index": int(item_block.get("track_index") or 1),
        }
        row, row_err = _build_append_clip_info_dict(root_folder, ci, 0, timeline_start)
        if row_err:
            return {"success": False, "error": f"swap append failed: {row_err.get('error')}", "lifted": lift}
        # No mediaType on the clip info: the replacement appends video+audio
        # linked, mirroring the video + linked-audio lift above.
        appended = mp.AppendToTimeline([row])
        after = _edit_engine_capture(tl)
        after["track_counts"] = _edit_engine_track_counts(tl)
        run_id = _analysis_runs.current_run_id()
        try:
            _brain_edits.log_brain_edit(
                project_root=project_root,
                analysis_run_id=run_id or "edit-engine",
                edit_type="edit_engine.swap_result",
                tool_name="edit_engine",
                action_name="execute_swap",
                timeline_after=tl.GetName(),
                target_metric=_brain_edits.METRIC_CLIP_COUNT,
                metric_direction="target_value",
                before_value=before.get("clip_count"),
                after_value=after.get("clip_count"),
                rationale=(
                    f"Swapped slot {item_block.get('timeline_start_frame')}-"
                    f"{item_block.get('timeline_end_frame')} with "
                    f"{alternate.get('clip_name')} shot {alternate.get('shot_index')}: "
                    f"{alternate.get('rationale')}"
                ),
                params={"plan_id": plan.get("plan_id"), "alternate_index": alt_index},
                result_summary={"appended": bool(appended)},
            )
        except Exception:
            pass
        _edit_engine_mod.mark_plan_executed(project_root, plan["plan_id"], {
            "alternate_index": alt_index,
            "replacement": alternate.get("clip_name"),
            "before": before,
            "after": after,
        })
        readback: Dict[str, Any] = {"before": before, "after": after}
        readback["audio_accounting"] = {
            "linked_audio_tracks_lifted": linked_audio_indices,
            "audio_items_lifted": (audio_lift or {}).get("deleted", 0),
            "video_items_lifted": lift.get("deleted", 0),
            **({"note": audio_note} if audio_note else {}),
        }
        return {
            "success": bool(appended),
            "timeline_name": tl.GetName(),
            "replaced_slot": [item_block.get("timeline_start_frame"), item_block.get("timeline_end_frame")],
            "replacement": {
                "clip_name": alternate.get("clip_name"),
                "shot_index": alternate.get("shot_index"),
                "score": alternate.get("score"),
            },
            "readback": readback,
            "plan_id": plan.get("plan_id"),
        }

    return _unknown(action, [
        "plan_selects",
        "execute_selects",
        "plan_tighten",
        "execute_tighten",
        "plan_swap",
        "execute_swap",
        "list_plans",
        "get_plan",
    ])

def _auto_edit_project_context(p: Dict[str, Any], *, need_resolve: bool):
    """(resolve, proj, project_root, err) — same contract as edit_engine's."""
    analysis_root = p.get("analysis_root") or p.get("analysisRoot")
    if analysis_root and not os.path.isdir(str(analysis_root)):
        # A typo'd root must not silently fall back to the open project's store
        # (briefs/plans would be read from — or written to — the wrong place).
        return None, None, None, _err(
            f"analysis_root is not a directory: {str(analysis_root)!r}")
    explicit_root = str(analysis_root) if analysis_root else None
    if not need_resolve and explicit_root:
        # Offline actions with an explicit evidence root never touch Resolve.
        return None, None, explicit_root, None
    vctx = _destructive_versioning_provider()
    if vctx is not None:
        r, proj, project_root, _name = vctx
        return r, proj, explicit_root or project_root, None
    return None, None, None, _err(
        "No project context — open a Resolve project (or pass analysis_root for offline actions)."
    )

def _auto_edit_build_rows(plan: Dict[str, Any], record_offset: int = 0) -> List[Dict[str, Any]]:
    """CutList -> AppendToTimeline row dicts (pure; offline-testable).

    Ordering follows the proven append-rebuild mechanism: V1 speech with
    mirrored audio, V2 b-roll overlays as positioned appends, then the music
    on A2 trimmed to the cut. All frame ranges are half-open; record frames
    shift by ``record_offset`` (the intro-title footprint at the head of V1).
    """
    rows: List[Dict[str, Any]] = []
    for seg in plan.get("segments") or []:
        base = {
            "clip_id": seg.get("clip_id") or seg.get("clip_uuid"),
            "start_frame": int(seg["source_start_frame"]),
            "end_frame": int(seg["source_end_frame"]),
            "record_frame": int(seg.get("record_start_frame", 0)) + record_offset,
        }
        rows.append({**base, "track_index": 1, "media_type": 1, "role": "speech",
                     "punch_in": seg.get("punch_in")})
        # Montage segments carry NO production audio by default (#193 phase
        # 5.1). They never set audio_track_indices, so the `or [1]` fallback
        # used to mirror every B-roll shot's camera audio onto A1 — wind,
        # traffic, handling noise, at unity gain, straight under the music
        # track on A2. Nothing in the plan, the summary or the skill mentioned
        # it and there was no knob. A music-cut montage wants the track alone;
        # a host that genuinely wants nat sound opts back in per plan.
        if seg.get("role") in _auto_edit_mod.cut_ir.MONTAGE_SEGMENT_ROLES and not (
                plan.get("keep_camera_audio") or seg.get("audio_track_indices")):
            continue
        for audio_track in (seg.get("audio_track_indices") or [1]):
            rows.append({**base, "track_index": int(audio_track), "media_type": 2,
                         "role": "speech_audio"})
    for overlay in plan.get("overlays") or []:
        rows.append({
            "clip_id": overlay.get("clip_id") or overlay.get("clip_uuid"),
            "start_frame": int(overlay["source_start_frame"]),
            "end_frame": int(overlay["source_end_frame"]),
            "record_frame": int(overlay.get("record_start_frame", 0)) + record_offset,
            "track_index": int(overlay.get("track_index") or 2),
            "media_type": 1,
            "role": "broll",
        })
    music = plan.get("music")
    if music:
        duration = int(music.get("record_end_frame", 0)) - int(music.get("record_start_frame", 0))
        if duration > 0:
            rows.append({
                "clip_path": music.get("bed_path") or music.get("path"),
                "start_frame": 0,
                "end_frame": duration,
                "record_frame": int(music.get("record_start_frame", 0)) + record_offset,
                "track_index": int(music.get("track_index") or 2),
                "media_type": 2,
                "role": "music",
            })
    return rows

def _map_montage_items_to_segments(items, segments, title_offset, *, record_offset=0):
    """Pair each V1 item with the plan segment it was built from — shared
    by the grade `match` stage and the motion/flash/retime stage below.

    Positional mapping (item i -> segment i - title_offset) is correct on
    a BUILT timeline, where V1 holds exactly the title plus one item per
    segment. It is wrong on a POLISHED one: a cross-dissolve is itself a
    V1 item, so every shot after the first dissolve shifted by one and got
    another shot's look bucket and beat directive — and SKILL.md actively
    steers hosts into `finish(target="polished", grade={"match": ...},
    motion={})`, the exact combination that trips it (#193 phase 6.2.5).

    So match by RECORD FRAME when the item starts allow it: each segment's
    record_start_frame (+ the title's footprint) is where its item begins,
    and a transition's own start matches no segment, so it drops out
    instead of consuming a segment. Falls back to the proven positional
    walk when start frames can't be read.

    Returns ``(pairs, stats)``: ``pairs`` is a list of ``(item, seg_idx, seg)``
    triples (the matching logic is unchanged — this only stops discarding
    what it already knew). ``stats`` is ``{"mode", "item_count",
    "planned_segments", "matched_segments", "unmatched_segment_indices"}`` —
    a caller that used to read `len(items)` as its denominator silently
    reported "0 applied" and "N of N" for a segment that was simply dropped,
    indistinguishable from a segment that legitimately had no directive
    (issue #203).
    """
    item_offset = 1 if title_offset > 0 else 0
    starts = []
    try:
        starts = [_frame_int(item.GetStart()) for item in items]
    except Exception:
        starts = []
    # Every start must be a real frame number. A Resolve build that can't
    # report them (or a double that doesn't) falls back to the positional
    # walk rather than mapping against Nones.
    if starts and all(isinstance(x, int) and not isinstance(x, bool) for x in starts):
        timeline_start = min(starts)
        by_frame = {}
        for idx, seg in enumerate(segments):
            expected = int(seg.get("record_start_frame", 0)) + record_offset
            by_frame.setdefault(expected, idx)
        used = set()
        matched = []
        for item, start in zip(items, starts):
            # Item starts are absolute; segment frames are timeline-start
            # relative, so normalise before looking up.
            seg_idx = by_frame.get(start - timeline_start)
            if seg_idx is None or seg_idx in used:
                continue
            used.add(seg_idx)
            matched.append((item, seg_idx, segments[seg_idx]))
        # Only trust it if it explains essentially the whole cut; a partial
        # match means the assumption is off and positional is the safer bet.
        if len(matched) >= len(segments):
            unmatched = [i for i in range(len(segments)) if i not in used]
            return matched, {
                "mode": "record_frame",
                "item_count": len(items),
                "planned_segments": len(segments),
                "matched_segments": len(used),
                "unmatched_segment_indices": unmatched,
            }
    pairs = []
    matched_idxs = set()
    for i, item in enumerate(items):
        seg_idx = i - item_offset
        if 0 <= seg_idx < len(segments):
            pairs.append((item, seg_idx, segments[seg_idx]))
            matched_idxs.add(seg_idx)
    unmatched = [i for i in range(len(segments)) if i not in matched_idxs]
    return pairs, {
        "mode": "positional",
        "item_count": len(items),
        "planned_segments": len(segments),
        "matched_segments": len(matched_idxs),
        "unmatched_segment_indices": unmatched,
    }


def _compute_beat_alignment(
    segments: List[Dict[str, Any]], item_starts: List[int], *,
    item_offset: int = 0, record_offset: int = 0,
) -> Dict[str, Any]:
    """Pure/offline-testable (issue #181, phase 6/6 of the montage-quality
    epic): verify each built V1 item's actual start frame — already
    timeline-start-relative — matches its plan segment's ``record_start_frame``
    exactly. Phase 2 guarantees ``record_start_frame`` is itself a beat-grid
    frame, so an exact per-segment match upholds "every item lands on a beat"
    more precisely than a bare set-membership check would.

    ``item_offset`` skips the intro title's own item (item 0) when one was
    built; ``record_offset`` is that same title's frame footprint, added to
    every expected position. Segments beyond ``item_starts`` (or vice versa)
    are simply not compared — a count mismatch shows up in ``checked``
    being smaller than ``len(segments)``, not as a spurious deviation.
    """
    deviations: List[Dict[str, Any]] = []
    checked = 0
    for i, actual in enumerate(item_starts):
        seg_idx = i - item_offset
        if seg_idx < 0 or seg_idx >= len(segments):
            continue
        expected = int(segments[seg_idx].get("record_start_frame", 0)) + record_offset
        checked += 1
        if actual != expected:
            deviations.append({
                "segment": seg_idx, "expected": expected, "actual": actual,
                "deviation_frames": actual - expected,
            })
    return {"checked": checked, "deviations": deviations}

def _auto_edit_ffprobe_ok(path: str) -> Tuple[bool, str]:
    """Light ffprobe validation; degrades to extension-only when absent."""
    import shutil as _shutil
    if _shutil.which("ffprobe") is None:
        return True, "ffprobe not installed — existence check only"
    try:
        proc = safe_run(
            ["ffprobe", "-v", "error", "-show_entries", "format=duration",
             "-of", "default=nw=1", path],
            capture_output=True, timeout=30, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        return False, f"ffprobe failed: {exc}"
    if proc.returncode != 0:
        return False, (proc.stderr or b"").decode("utf-8", "replace")[:200] or "unreadable media"
    return True, ""

def _is_montage_plan(plan: Dict[str, Any]) -> bool:
    """CutLists carry no genre field (montage adds roles, not schema) — detect
    by role instead of threading genre through plan/revise/summary calls."""
    return any(
        seg.get("role") in _auto_edit_mod.cut_ir.MONTAGE_SEGMENT_ROLES
        for seg in (plan.get("segments") or [])
    )

@mcp.tool()
@_bridge_serialized
@_destructive_op("auto_edit")
@_missing_param_envelope
async def auto_edit(action: str, params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Autonomous brief-to-rendered-video pipeline (talking head + montage).

    The user states a brief (files, music, target length); analysis runs; the
    decision layer assembles a CutList; ONE human checkpoint (approve_cut,
    confirm-token gated, includes the music-bed-render consent line) approves
    it; then the timeline is append-rebuilt and finished (grade/motion/
    subtitles/render/QC). Revisions rebuild — timelines are stateless artifacts.

    Actions:
      start_brief(files, music?, target_duration_seconds?, genre?, deliverable?,
        title_text?, options?) -> {brief_id, analysis_job_id, vision_enabled} —
        validates files (exist + ffprobe), scaffolds Footage/Music bins (safe
        import), kicks a media_analysis batch job (transcription + visuals per
        defaults; the host completes commit_vision for deep passes).
        options.vision defaults ON for genre="montage" (its shot pool is
        vision-derived and it cannot plan without one) and OFF otherwise;
        `deliverable` is a stored label with no effect on the render.
      brief_status(brief_id) | status(brief_id) -> {brief, analysis?} — brief
        state; polls the analysis job and advances analyzing -> ready.
      plan_cut(brief_id, scout?, scout_confirm_token?) -> {plan_id, plan,
        summary} — build the CutList from evidence (word-level Pass-1, story
        beats, b-roll similarity) and render the markdown checkpoint summary.
        MONTAGE: scout (default true) may return a deep_vision in-point OFFER
        for one not-yet-scouted clip INSTEAD of a plan — read its frames,
        commit, call plan_cut again. Cache-aware, never re-offers, never
        blocks; pass scout=false to skip. Mixed source frame rates are
        supported: the timeline is cut at the most common footage rate and each
        shot keeps source frames in its own rate (Resolve conforms off-rate
        media by preserving its real-time length), so the beat lock holds.
      revise_cut(brief_id, notes?, edits?) -> revision+1 — structured overrides
        (reorder/keep/drop/title), new plan_id, old revisions stay loadable.
        Drop indices refer to the plan as displayed: a drop-only batch removes
        exactly those segments (listed in any order); drops mixed with
        reorder/keep must be descending or the batch is rejected.
      get_cut_summary(plan_id, format?) -> {summary} — markdown (default) or json.
      approve_cut(plan_id, music_bed_consent?, confirm_token?) — THE one human
        checkpoint. The confirm-token preview embeds the cut summary and the
        music-bed-render consent line; consent decides static vs rendered_bed.
      build_timeline(plan_id, title_generator?, confirm_token?) -> {timeline_name,
        readback} — append-rebuild from the approved CutList: intro title, V1
        speech + mirrored audio, V2 b-roll, punch-in zoom, A2 music (ducked bed
        only when consented). Readback-verified.
      polish_timeline(plan_id, options?, confirm_token?) -> {polished_timeline,
        transitions, lower_thirds, speed_ramps, media_link} — Phase-2 pro polish
        the scripting API can't do. Exports the built timeline as .drt, runs
        verified drp-format vendor ops (cross-dissolves at flagged cuts via
        place_transition, lower-thirds on an upper track via place_fusion_title,
        speed ramps via retime_clip), and reimports as a NEW "(polished)"
        timeline; export-then-modify keeps media linked. options:
        lower_thirds[], dissolve_at_segments[], dissolve_on_beat_change,
        dissolve_frames, lower_third_frames/track, no_dissolves,
        no_lower_thirds, no_retime.
        MONTAGE defaults to no_dissolves (every montage cut is a source change)
        and authors retime_clip speed ramps for retime-flagged segments.
      finish(plan_id, grade?, motion?, subtitles?, render?, target?,
        confirm_token?) -> {output} — grade (lut_path | cdl | drx_path),
        optional subtitles, validated render; reports the output path.
        target selects the "built" (default) or "polished" timeline.
        MONTAGE: grade={"match": {bucket: {"cdl": ...}}} applies per-look-bucket
        CDLs as stage 1 beneath the uniform look — the plan's own
        look_buckets ({bucket: <raw CDL>}) is accepted as-is; motion={} applies the
        beat-locked Fusion motion/flash/shake/fadeout/look pass (motion=
        {"look": false} drops vignette/grain/letterbox); a visual-QC host-vision
        request is returned after a successful render unless qc=false.
      commit_qc(plan_id, qc_report) -> {findings, suggested_edit?} — finishes
        finish()'s visual-QC handoff: normalizes the host's findings and, for
        one tied to a specific cut, returns a suggested revise_cut edit.
        Read-only against the plan; no confirm token.
      list_briefs() -> {briefs}
    """
    from src.domains.timeline_edit.actions import _build_append_clip_info_dict, _unique_timeline_name
    from src.domains.media_pool_ingest.actions import _ensure_folder_path, _find_clip_by_file_path, _safe_import_media
    from src.domains.timeline_conform_interchange.actions import _export_timeline_checked, _import_timeline_checked, _timeline_media_coverage
    from src.domains.color_grade.actions import _normalize_cdl
    from src.domains.render_deliver.actions import _prepare_render_job, _render_cut_summary_for
    from src.domains.audio_fairlight.actions import _safe_create_subtitles
    from src.domains.media_analysis.actions import media_analysis
    p = _tool_params(params)

    def _plan_id_param() -> str:
        return str(p.get("plan_id") or p.get("planId") or "")

    def _brief_id_param() -> str:
        return str(p.get("brief_id") or p.get("briefId") or "")

    if action == "start_brief":
        r, proj, project_root, err = _auto_edit_project_context(p, need_resolve=True)
        if err:
            return err
        files = p.get("files") or []
        music = p.get("music")
        # Fail-fast pre-flight: catch bad inputs before the expensive ffprobe
        # pass and irreversible media import below. create_brief re-validates as
        # the authoritative check for direct callers — deliberate layering.
        problems = _auto_edit_mod.validate_brief_inputs(
            files=files, music=music,
            target_duration_seconds=p.get("target_duration_seconds") or p.get("targetDurationSeconds"),
            genre=p.get("genre") or "talking_head",
            deliverable=p.get("deliverable") or "youtube_1080p",
            title_text=p.get("title_text") or p.get("titleText"),
        )
        # Genre-specific rules (montage requires music) live here, not in
        # auto_edit.py — that module stays unaware of montage's own rules to
        # avoid a circular import (montage_edit already imports auto_edit).
        if str(p.get("genre") or "talking_head") == _montage_edit_mod.GENRE:
            problems.extend(_montage_edit_mod.validate_montage_brief_inputs(
                files=files, music=music,
                target_duration_seconds=p.get("target_duration_seconds") or p.get("targetDurationSeconds"),
            ))
        probe_targets = []
        for path in list(files) + ([music] if music else []):
            if not isinstance(path, str) or not os.path.isfile(path):
                problems.append(f"file not found: {path!r}")
                continue
            probe_targets.append(path)
        if probe_targets:
            # The probes are independent; run them concurrently instead of
            # paying one spawn+probe latency per file back to back. Probes can
            # take up to 30s each, and auto_edit is async — keep the wait off
            # the event loop.
            def _probe_all():
                from concurrent.futures import ThreadPoolExecutor
                with ThreadPoolExecutor(max_workers=min(4, len(probe_targets))) as pool:
                    return list(pool.map(_auto_edit_ffprobe_ok, probe_targets))
            import anyio
            for path, (ok, why) in zip(
                    probe_targets, await anyio.to_thread.run_sync(_probe_all)):
                if not ok:
                    problems.append(f"unreadable media {path!r}: {why}")
        if problems:
            return _err("invalid brief: " + "; ".join(problems))
        mp = proj.GetMediaPool()
        if not mp:
            return _err("No media pool")
        imported: Dict[str, Any] = {}
        for bin_name, paths in (("Footage", list(files)), ("Music", [music] if music else [])):
            if not paths:
                continue
            _folder, folder_err = _ensure_folder_path(mp, bin_name)
            if folder_err:
                return folder_err
            result = _safe_import_media(mp, {"paths": paths, "target_folder": bin_name})
            if result.get("error"):
                return result
            imported[bin_name] = result
        created = _auto_edit_mod.create_brief(
            project_root,
            files=list(files), music=music,
            target_duration_seconds=p.get("target_duration_seconds") or p.get("targetDurationSeconds"),
            genre=str(p.get("genre") or "talking_head"),
            deliverable=str(p.get("deliverable") or "youtube_1080p"),
            title_text=p.get("title_text") or p.get("titleText"),
            options=p.get("options") or {},
        )
        if not created.get("success"):
            return _err("; ".join(created.get("problems") or [created.get("error") or "brief failed"]))
        brief_id = created["brief_id"]
        analysis_job_id = None
        analysis_warning = None
        # Transcription is the load-bearing artifact for planning. LLM vision
        # (host_chat_paths) needs an interactive host to commit frames, which an
        # autonomous brief cannot satisfy, so it is off by default here (opt in
        # via options.vision). An explicit sampling_mode stops start_batch_job
        # from returning its first-run frame-sampling prompt instead of a job.
        #
        # MONTAGE IS THE EXCEPTION and defaults vision ON — see
        # auto_edit.resolve_vision_default, which owns that rule and is unit
        # tested (#193 phase 1). Its entire candidate pool is the `shots`
        # table, whose one writer is fed by `visual.shot_descriptions`, a
        # vision-only artifact, so vision-off is a guaranteed plan_cut failure
        # rather than a conservative default.
        brief_options = p.get("options") or {}
        _vision_on, vision_warning = _auto_edit_mod.resolve_vision_default(
            p.get("genre") or "talking_head", brief_options)
        try:
            kicked = await media_analysis("start_batch_job", {
                "target": {"type": "bin", "path": "Footage", "recursive": False},
                "name": f"auto_edit {brief_id}",
                "analysis_root": project_root,
                "sampling_mode": brief_options.get("sampling_mode") or "adaptive_capped",
                "transcription": {"enabled": True, "allow_model_download": True},
                "vision": {"enabled": _vision_on},
            })
            # create_batch_job nests the id under "job"; a first-run sampling
            # prompt or a capability gap returns no job at all.
            analysis_job_id = ((kicked or {}).get("job") or {}).get("job_id")
            if not analysis_job_id:
                analysis_warning = (kicked or {}).get("error") or (
                    kicked or {}).get("message") or "analysis kick returned no job_id"
        except Exception as exc:
            analysis_warning = f"analysis kick failed: {type(exc).__name__}: {exc}"
        _auto_edit_mod.advance_brief(
            project_root, brief_id,
            "analyzing" if analysis_job_id else "created",
            analysis_job_id=analysis_job_id,
        )
        out = {
            "success": True,
            "brief_id": brief_id,
            "analysis_job_id": analysis_job_id,
            "imported": imported,
            # Reported so the host can SEE whether the shot pool is going to
            # exist, at the step where it can still be fixed cheaply, instead
            # of inferring it from a plan_cut error two steps later.
            "vision_enabled": _vision_on,
            "next": "poll brief_status until state=ready, then plan_cut",
        }
        warnings = [w for w in (vision_warning, analysis_warning) if w]
        if analysis_warning:
            warnings[-1] = analysis_warning + " — run media_analysis manually, then plan_cut."
        if warnings:
            out["warning"] = " | ".join(warnings)
        return out

    if action in ("brief_status", "status"):
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        brief = _auto_edit_mod.load_brief(project_root, _brief_id_param())
        if not brief:
            return _err(f"brief not found: {_brief_id_param()!r}")
        analysis = None
        if brief.get("state") == "analyzing" and brief.get("analysis_job_id"):
            job_id = brief["analysis_job_id"]
            # brief_status is the ONLY surface that drives this job's slices —
            # start_brief just queues it, nothing else pumps it. Run bounded
            # slices until the job is terminal or this call's time budget is
            # spent; large briefs finish across successive polls.
            budget = _time.monotonic() + 300
            try:
                analysis = await media_analysis("batch_job_status", {"job_id": job_id})
                _terminal = ("completed", "completed_with_errors", "canceled", "failed")
                while str((analysis or {}).get("status") or "").lower() not in _terminal:
                    if _time.monotonic() >= budget:
                        break
                    sliced = await media_analysis("run_batch_job_slice", {
                        "job_id": job_id, "max_clips": 4, "max_seconds": 240})
                    analysis = (sliced or {}).get("job") or await media_analysis(
                        "batch_job_status", {"job_id": job_id})
                    # No progress (nothing pending / slice failed) — stop looping.
                    if not (sliced or {}).get("success") or not (sliced or {}).get("processed_count"):
                        break
                job_state = str((analysis or {}).get("status") or "").lower()
                # Terminal job statuses are completed | completed_with_errors |
                # canceled (media_analysis_jobs); a partly-failed batch still
                # readies the brief — planning fails honestly on missing clips.
                if job_state in ("completed", "completed_with_errors"):
                    brief = _auto_edit_mod.advance_brief(
                        project_root, brief["plan_id"], "ready")["brief"]
            except Exception as exc:
                analysis = {"error": f"{type(exc).__name__}: {exc}"}
        return {"success": True, "brief": brief,
                **({"analysis": analysis} if analysis is not None else {})}

    if action == "plan_cut":
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        brief = _auto_edit_mod.load_brief(project_root, _brief_id_param())
        if not brief:
            return _err(f"brief not found: {_brief_id_param()!r}")
        if brief.get("state") in ("created", "analyzing"):
            # Planning needs evidence; move to ready only if the DB has it —
            # build_cut_list_for_brief fails honestly when analysis is missing.
            _auto_edit_mod.advance_brief(project_root, brief["plan_id"], "ready")
            brief = _auto_edit_mod.load_brief(project_root, brief["plan_id"]) or brief
        genre = str(brief.get("genre") or "talking_head")
        if genre == _montage_edit_mod.GENRE:
            # In-point scouting (issue #178): on by default, escape hatch via
            # scout=false. Offers the deep_vision handoff for exactly one
            # not-yet-scouted clip and returns THAT instead of a plan — read
            # its frames, commit, then call plan_cut again. Cache-aware
            # (scout_handoff_if_needed returns None once every shot already
            # has scout data), so this never re-offers on a later revision,
            # and it never blocks planning: pass scout=false, or just ignore
            # the offer and call plan_cut again, to plan with whatever
            # best_moment/shot-start in-points are already available.
            if p.get("scout", True):
                # Accept the key the OFFER handed back (`confirm_token`) as
                # well as this action's own parameter name — echoing what you
                # were given is the obvious move, and rejecting it silently
                # re-served the identical offer forever (#193 phase 2.4).
                scout_offer = _montage_edit_mod.scout_handoff_if_needed(
                    project_root, brief,
                    confirm_token=(p.get("scout_confirm_token")
                                   or p.get("scoutConfirmToken")
                                   or p.get("confirm_token")))
                if scout_offer is not None:
                    return scout_offer
            # No ducking/voiceover in montage — the loudness-bed-gain pass
            # exists only to feed talking-head's ducking ladder.
            built = _montage_edit_mod.build_cut_list_for_brief(project_root, brief)
        else:
            music_gain_db = None
            if brief.get("music") and os.path.isfile(str(brief["music"])):
                music_path = str(brief["music"])
                try:
                    music_mtime = os.path.getmtime(music_path)
                except OSError:
                    music_mtime = None
                gain_cache = brief.get("music_gain_cache") or {}
                if gain_cache.get("path") == music_path and gain_cache.get("mtime") == music_mtime:
                    music_gain_db = gain_cache.get("gain_db")
                else:
                    # Full ffmpeg loudness pass — measure once per music file and
                    # cache on the brief so re-planning doesn't re-decode it.
                    bed = _music_analysis_mod.analyze_music_bed(music_path)
                    music_gain_db = bed.get("gain_db")
                    if music_gain_db is not None:
                        _auto_edit_mod.advance_brief(
                            project_root, brief["plan_id"], str(brief.get("state") or "ready"),
                            music_gain_cache={"path": music_path, "mtime": music_mtime,
                                              "gain_db": music_gain_db})
            built = _auto_edit_mod.build_cut_list_for_brief(
                project_root, brief, music_gain_db=music_gain_db)
        if not built.get("success"):
            return _err(built.get("error") or "planning failed",
                        ) | {"problems": built.get("problems") or []}
        plan = built["plan"]
        _auto_edit_mod.advance_brief(
            project_root, brief["plan_id"], "planned", latest_plan_id=plan["plan_id"])
        return {
            "success": True,
            "brief_id": brief["plan_id"],
            "plan_id": plan["plan_id"],
            "plan": plan,
            "summary": _render_cut_summary_for(plan),
            "next": "review the summary; approve_cut(plan_id) or revise_cut(brief_id, edits)",
        }

    if action == "revise_cut":
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        brief = _auto_edit_mod.load_brief(project_root, _brief_id_param())
        if not brief:
            return _err(f"brief not found: {_brief_id_param()!r}")
        plan_id = _plan_id_param() or str(brief.get("latest_plan_id") or "")
        if not plan_id:
            return _err("brief has no cut list yet — plan_cut first")
        revised = _auto_edit_mod.apply_revision(
            project_root, plan_id,
            notes=str(p.get("notes") or ""), edits=p.get("edits"))
        if not revised.get("success"):
            return _err(revised.get("error") or "revision failed",
                        ) | {"problems": revised.get("problems") or []}
        plan = revised["plan"]
        _auto_edit_mod.advance_brief(
            project_root, brief["plan_id"], "planned", latest_plan_id=plan["plan_id"])
        return {
            "success": True,
            "brief_id": brief["plan_id"],
            "plan_id": plan["plan_id"],
            "revision": plan.get("revision"),
            "plan": plan,
            "summary": _render_cut_summary_for(plan),
        }

    if action == "get_cut_summary":
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, _plan_id_param())
        if not plan or plan.get("_corrupt") or plan.get("kind") != _auto_edit_mod.cut_ir.CUT_LIST_KIND:
            return _err(f"cut list not found: {_plan_id_param()!r}")
        if str(p.get("format") or "markdown").lower() == "json":
            return {"success": True, "plan": plan}
        return {"success": True, "plan_id": plan["plan_id"],
                "summary": _render_cut_summary_for(plan)}

    if action == "approve_cut":
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, _plan_id_param())
        if not plan or plan.get("_corrupt") or plan.get("kind") != _auto_edit_mod.cut_ir.CUT_LIST_KIND:
            return _err(f"cut list not found (or failed its fingerprint check): {_plan_id_param()!r}")
        is_montage = _is_montage_plan(plan)
        # Montage has no voiceover to duck under — force static regardless of
        # what's passed, never honor a stray consent flag into a rendered
        # derivative for a genre that was designed to never need one.
        music_bed_consent = False if is_montage else bool(
            p.get("music_bed_consent") or p.get("musicBedConsent"))
        # Tier-2 ducking (issue #14): write the bed gain into the .drt volume during
        # polish_timeline — no rendered derivative, so no consent needed.
        prefer_drt_ducking = False if is_montage else bool(
            p.get("prefer_drt_ducking") or p.get("preferDrtDucking"))
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            preview: Dict[str, Any] = {
                "operation": "auto_edit.approve_cut",
                "warning": "THE one human checkpoint: approving authorizes the "
                           "timeline build and downstream finish steps.",
                "plan_id": plan["plan_id"],
                "revision": plan.get("revision"),
                "estimates": plan.get("estimates"),
                "summary_markdown": _render_cut_summary_for(plan),
            }
            if plan.get("music") and not is_montage:
                preview["music_bed_consent_requested"] = music_bed_consent
                preview["prefer_drt_ducking"] = prefer_drt_ducking
                # drt_automation writes no derivative media, so the consent line is
                # moot when it's chosen.
                if not prefer_drt_ducking:
                    preview["music_bed_consent_line"] = _auto_edit_mod.MUSIC_BED_CONSENT_LINE
            return _issue_confirm_token(
                action="auto_edit.approve_cut", params=p, preview=preview)
        blocked = _consume_confirm_token(action="auto_edit.approve_cut", params=p)
        if blocked:
            return blocked
        approved = _auto_edit_mod.mark_approved(
            project_root, plan["plan_id"], music_bed_consent=music_bed_consent,
            prefer_drt_ducking=prefer_drt_ducking)
        if not approved.get("success"):
            return _err(approved.get("error") or "approval failed")
        if approved["plan"].get("brief_id"):
            _auto_edit_mod.advance_brief(
                project_root, approved["plan"]["brief_id"], "approved")
        return {
            "success": True,
            "plan_id": approved["plan_id"],
            "approved_at": approved["plan"].get("approved_at"),
            "music_bed_consent": music_bed_consent,
            "ducking_mode": (approved["plan"].get("music") or {}).get("ducking", {}).get("mode"),
            "next": "build_timeline(plan_id)",
        }

    if action == "build_timeline":
        _r, proj, project_root, err = _auto_edit_project_context(p, need_resolve=True)
        if err:
            return err
        gate = _auto_edit_mod.require_approved_plan(project_root, _plan_id_param())
        if not gate.get("success"):
            return _err(gate.get("error") or "plan gate failed")
        plan = gate["plan"]
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            ducking = ((plan.get("music") or {}).get("ducking") or {})
            return _issue_confirm_token(
                action="auto_edit.build_timeline", params=p,
                preview={
                    "operation": "auto_edit.build_timeline",
                    "warning": "Creates a NEW timeline from the approved CutList; "
                               "no existing timeline is modified."
                               + (" A ducked music-bed file will be rendered "
                                  "(consented at approve_cut)."
                                  if ducking.get("mode") == "rendered_bed" else ""),
                    "plan_id": plan["plan_id"],
                    "segments": len(plan.get("segments") or []),
                    "overlays": len(plan.get("overlays") or []),
                    "estimates": plan.get("estimates"),
                },
            )
        blocked = _consume_confirm_token(action="auto_edit.build_timeline", params=p)
        if blocked:
            return blocked
        mp = proj.GetMediaPool()
        if not mp:
            return _err("No media pool")
        root_folder = mp.GetRootFolder()
        fps = float(plan.get("fps") or 24.0)

        # Tier-1 ducked bed (consent-gated at approve_cut; refusal falls back
        # to the original music at a static level).
        music = plan.get("music")
        bed_note = None
        if music and (music.get("ducking") or {}).get("mode") == "rendered_bed":
            from src.domains.media_analysis.utils import analysis_memory as _analysis_memory
            bed_dir = os.path.join(_analysis_memory.memory_dir(project_root), "auto_edit")
            bed_path = os.path.join(bed_dir, f"{plan['plan_id']}_bed.wav")
            duration_s = (int(music.get("record_end_frame", 0))
                          - int(music.get("record_start_frame", 0))) / fps
            bed = _music_analysis_mod.render_ducked_bed(
                str(music.get("path")), bed_path,
                duration_seconds=duration_s,
                gain_db=music.get("gain_db"),
                user_approved_render=bool((music.get("ducking") or {}).get("user_approved_render")),
            )
            if bed.get("success"):
                music["bed_path"] = bed["output_path"]
                imported_bed = _safe_import_media(
                    mp, {"paths": [bed["output_path"]], "target_folder": "Music"})
                if imported_bed.get("error"):
                    bed_note = f"bed import failed ({imported_bed.get('error')}); using original music"
                    music.pop("bed_path", None)
            else:
                bed_note = bed.get("error")

        name = _unique_timeline_name(proj, str(
            p.get("timeline_name") or p.get("timelineName")
            or ((plan.get("titles") or [{}])[0].get("text") if plan.get("titles") else None)
            or "Auto Edit"))

        # A new timeline inherits the PROJECT's current default frame rate,
        # which may not match the footage's own fps (plan["fps"]) — every
        # record-frame position below is computed assuming the footage's fps,
        # so a mismatched timeline silently stretches real time (live
        # finding: a montage planned for 899 frames read back as 1123 actual
        # frames because the timeline defaulted to 23.976/24fps against
        # 29.97fps footage). The Resolve API docs document exactly this
        # pattern as `Project:SetSetting('timelineFrameRate', x)` — setting
        # it on the ALREADY-CREATED Timeline object returned False live
        # (Studio 21.0.2.4), so this must happen on the project, before
        # CreateEmptyTimeline. Verified by read-back rather than trusting the
        # SetSetting return value alone.
        try:
            fps_set_ok = bool(proj.SetSetting("timelineFrameRate", str(fps)))
        except Exception:
            fps_set_ok = False

        tl = mp.CreateEmptyTimeline(name)
        if not tl:
            return _err("Failed to create timeline")
        # #113 Tier 1: the whole build (title, appends, overlays) targets the
        # current timeline implicitly. Building into the wrong one is worse than
        # not building at all, so fail here instead.
        if not _set_current_timeline(proj, tl):
            return _err(f"Created timeline '{name}' but could not make it current; "
                        "refusing to build, which would target the wrong timeline")
        timeline_start = _timeline_start_frame(tl)
        build_errors: List[Dict[str, Any]] = []

        try:
            match = re.search(r"\d+(?:\.\d+)?", str(tl.GetSetting("timelineFrameRate") or ""))
            actual_fps = float(match.group(0)) if match else None
        except Exception:
            actual_fps = None
        if actual_fps is not None and abs(actual_fps - fps) > 0.01:
            build_errors.append({
                "error": f"timeline frame rate is {actual_fps}, not the footage's {fps} — "
                         "every record-frame position in this build lands at the wrong real-world time"
                         + ("" if fps_set_ok else " (Project.SetSetting(timelineFrameRate) returned False)"),
            })

        # 1) Intro title at the head of V1 — the only reliable placement.
        title_result = None
        record_offset = 0
        titles = plan.get("titles") or []
        if titles:
            generator = str(p.get("title_generator") or p.get("titleGenerator") or "Text")
            try:
                inserted = bool(tl.InsertTitleIntoTimeline(generator))
            except Exception as exc:
                inserted = False
                title_result = {"inserted": False, "error": f"{type(exc).__name__}: {exc}"}
            if inserted:
                text_set = False
                try:
                    items = tl.GetItemListInTrack("video", 1) or []
                    if items:
                        title_item = items[0]
                        record_offset = max(
                            0, int(title_item.GetEnd()) - int(timeline_start or 0))
                        for key in ("Text", "Text1", "StyledText"):
                            try:
                                if title_item.SetProperty(key, str(titles[0].get("text") or "")):
                                    text_set = True
                                    break
                            except Exception:
                                continue
                except Exception:
                    pass
                title_result = {"inserted": True, "text_set": text_set,
                                "record_offset": record_offset}

        # 2..5) Speech + mirrored audio, b-roll overlays, music — one append pass.
        rows = _auto_edit_build_rows(plan, record_offset)
        # Overlay rows (and offline-analyzed sources) may carry only the
        # analysis-DB clip_uuid, which _find_clip cannot resolve; translate
        # any unknown id to a media-pool clip via the DB's recorded file path.
        pending_ids = {row["clip_id"] for row in rows
                       if row.get("clip_id") and not _find_clip(root_folder, row["clip_id"])}
        if pending_ids:
            from src.core import timeline_brain_db as _tbdb
            translated: Dict[str, Any] = {}
            try:
                conn = _tbdb.connect(project_root)
                for cid in pending_ids:
                    db_row = conn.execute(
                        "SELECT file_path, clip_name FROM clips WHERE clip_uuid = ?",
                        (cid,)).fetchone()
                    if db_row is None:
                        continue
                    mp_clip = _find_clip_by_file_path(
                        root_folder, str(db_row["file_path"] or db_row["clip_name"] or ""))
                    if mp_clip:
                        translated[cid] = mp_clip.GetUniqueId()
            except Exception:
                pass
            for row in rows:
                if row.get("clip_id") in translated:
                    row["clip_id"] = translated[row["clip_id"]]
        built = []
        punch_targets = []
        for i, row in enumerate(rows):
            append_ci = dict(row)
            clip_path = append_ci.pop("clip_path", None)
            punch = append_ci.pop("punch_in", None)
            append_ci.pop("role", None)
            if clip_path and not append_ci.get("clip_id"):
                clip = _find_clip_by_file_path(root_folder, str(clip_path))
                if not clip:
                    build_errors.append({"index": i, "error": f"media pool clip not found for {clip_path!r}"})
                    continue
                append_ci["clip_id"] = clip.GetUniqueId()
                # Audio-only media (this is always the music row — video
                # segments resolve via clip_id above, never clip_path) gets
                # stamped with a "FPS" clip property at import time that need
                # not match the timeline's own fps (audio has no true
                # frames). AppendToTimeline's startFrame/endFrame trim is
                # interpreted in THAT stamped rate, not the timeline's — live
                # finding: a 899-frame/29.97fps trim (intended as 30.0s)
                # played back as 37.4s because the music clip was stamped at
                # 24fps. Every frame count here was computed assuming the
                # footage's fps, so rescale into the clip's own stamped
                # units, verified by reading it back rather than assuming it
                # matches.
                try:
                    clip_fps_raw = clip.GetClipProperty("FPS") or clip.GetClipProperty("Frame Rate")
                    clip_fps_match = re.search(r"\d+(?:\.\d+)?", str(clip_fps_raw or ""))
                    clip_fps = float(clip_fps_match.group(0)) if clip_fps_match else None
                except Exception:
                    clip_fps = None
                if clip_fps and clip_fps > 0 and abs(clip_fps - fps) > 0.01:
                    ratio = clip_fps / fps
                    append_ci["start_frame"] = int(round(float(append_ci["start_frame"]) * ratio))
                    append_ci["end_frame"] = int(round(float(append_ci["end_frame"]) * ratio))
            ci_row, row_err = _build_append_clip_info_dict(root_folder, append_ci, i, timeline_start)
            if row_err:
                build_errors.append({"index": i, "error": row_err.get("error")})
                continue
            built.append(ci_row)
            if punch and row.get("media_type") == 1:
                punch_targets.append({
                    "record_frame": int(append_ci["record_frame"]),
                    "zoom": float(punch.get("zoom") or _auto_edit_mod.PUNCH_IN_ZOOM),
                })
        # A positioned append to A2+ is SILENTLY DROPPED unless the audio track
        # already exists (verified live — api_truth #12 probe 6), so the music bed
        # on A2 vanishes without this. Create the audio tracks the rows target
        # before the append. (CreateEmptyTimeline starts with one audio track.)
        need_audio = max(
            [int(r.get("trackIndex", 1)) for r in built
             if int(r.get("mediaType", 1)) == 2] or [0])
        while need_audio and int(tl.GetTrackCount("audio") or 1) < need_audio:
            if not tl.AddTrack("audio"):
                # AddTrack can refuse (locked timeline, modal open); bail rather
                # than spin — the append below then drops the A2+ rows, which the
                # build_errors surface makes visible.
                build_errors.append({
                    "error": f"AddTrack('audio') refused; need {need_audio} audio "
                             f"tracks, have {tl.GetTrackCount('audio')}"})
                break
        appended = mp.AppendToTimeline(built) if built else None

        # 4) Punch-in zoom on jump-cut segments (static transform per item).
        punch_results = []
        if punch_targets:
            try:
                items = tl.GetItemListInTrack("video", 1) or []
                base = int(timeline_start or 0)
                items_by_record: Dict[int, Any] = {}
                for it in items:
                    items_by_record.setdefault(int(it.GetStart()) - base, it)
                for target in punch_targets:
                    hit = items_by_record.get(target["record_frame"])
                    if hit is None:
                        punch_results.append({**target, "applied": False, "reason": "item not found"})
                        continue
                    ok_x = bool(hit.SetProperty("ZoomX", target["zoom"]))
                    ok_y = bool(hit.SetProperty("ZoomY", target["zoom"]))
                    punch_results.append({**target, "applied": ok_x and ok_y})
            except Exception as exc:
                punch_results.append({"error": f"{type(exc).__name__}: {exc}"})

        # Beat-alignment readback (issue #181, phase 6/6 of the montage-
        # quality epic): the offline suite was green while cuts landed on
        # arbitrary 16th notes and record frames drifted, because nothing
        # asserted a cut lands where the PLAN says it lands. Phase 2 adds
        # that invariant at plan level; this is the built-timeline-level
        # check (_compute_beat_alignment, pure/testable), and it runs on
        # every montage build, not only in tests. A deviation is a build
        # error, not a warning — surfaced in build_errors the same way every
        # other build failure already is.
        beat_alignment = None
        if plan.get("grid_available"):
            segments = plan.get("segments") or []
            try:
                beat_items = tl.GetItemListInTrack("video", 1) or []
            except Exception as exc:
                beat_items = []
                build_errors.append(
                    {"error": f"beat-alignment readback: GetItemListInTrack failed: {type(exc).__name__}: {exc}"})
            base = int(timeline_start or 0)
            item_starts: List[int] = []
            item_start_errors: List[Dict[str, Any]] = []
            for idx, item in enumerate(beat_items):
                try:
                    item_starts.append(int(item.GetStart()) - base)
                except Exception as exc:
                    item_start_errors.append(
                        {"item_index": idx, "error": f"GetStart failed: {type(exc).__name__}: {exc}"})
                    item_starts.append(-1)  # sentinel: reads as a deviation, never silently skipped
            item_offset = 1 if record_offset > 0 else 0
            beat_alignment = _compute_beat_alignment(
                segments, item_starts, item_offset=item_offset, record_offset=record_offset)
            beat_alignment["deviations"] = item_start_errors + beat_alignment["deviations"]
            if beat_alignment["deviations"]:
                build_errors.append({
                    "error": f"{len(beat_alignment['deviations'])} item(s) off the beat grid "
                             f"after build: {beat_alignment['deviations']}",
                })

        readback = _edit_engine_capture(tl)
        try:
            usage = _timeline_versioning.capture_timeline_clip_usage(tl)
            by_type: Dict[str, int] = {}
            for usage_row in usage:
                by_type[usage_row["track_type"]] = by_type.get(usage_row["track_type"], 0) + 1
            readback["usage_summary"] = {"items": len(usage), "by_track_type": by_type}
        except Exception:
            pass
        _edit_engine_mod.mark_plan_executed(project_root, plan["plan_id"], {
            "timeline_name": tl.GetName(),
            "appended": len(built),
            "build_errors": build_errors,
            # Persist the intro-title footprint: polish_timeline shifts its op
            # positions by this record_offset so cross-dissolves/lower-thirds
            # line up with the built timeline's record frames.
            "title": title_result,
            "beat_alignment": beat_alignment,
            **readback,
        })
        if plan.get("brief_id"):
            _auto_edit_mod.advance_brief(
                project_root, plan["brief_id"], "built",
                built_timeline=tl.GetName())
        out = {
            "success": bool(appended),
            "timeline_name": tl.GetName(),
            "appended": len(built),
            "build_errors": build_errors,
            "title": title_result,
            "punch_ins": punch_results,
            "readback": readback,
            "plan_id": plan["plan_id"],
            "next": "finish(plan_id, render={target_dir}) to grade/subtitle/render",
        }
        if beat_alignment is not None:
            out["beat_alignment"] = beat_alignment
        if bed_note:
            out["music_bed_note"] = bed_note
        return out

    _MOTION_TRANSFORM_TOOL = "MCP_BeatPulse"
    _MOTION_FLASH_TOOL = "MCP_Flash"
    _MOTION_FADEOUT_TOOL = "MCP_Fadeout"
    _VIGNETTE_MASK_TOOL = "MCP_VignetteMask"
    _VIGNETTE_TOOL = "MCP_Vignette"
    _GRAIN_NOISE_TOOL = "MCP_Grain"
    _GRAIN_MERGE_TOOL = "MCP_GrainMerge"
    _RETIME_PROCESS_MAP = {"nearest": 1, "frame_blend": 2, "optical_flow": 3}

    # Look pass (issue #180 section B): InsertGeneratorIntoTimeline("Adjustment
    # Clip") was verified live (Resolve Studio 21.0.2.4) to ignore track_index/
    # track_type entirely — it always ripple-inserts onto whatever Resolve
    # considers the "current" video track, ripple-shifting every clip after
    # it. Not viable for a shared upper-track adjustment layer in an
    # unattended pipeline. Falls back to the issue's own documented
    # alternative: the same small per-clip vignette/grain nodes appended to
    # EVERY item's comp (still non-destructive, still adjustable afterward —
    # just not literally "once"). Letterbox uses the existing per-item Crop
    # property directly; no Fusion node needed for a straight top/bottom bar.
    _VIGNETTE_GAIN = 0.4         # corner darkening strength (issue #201: 0.55 was
                                  # compensating for a hard-edged mask; a soft falloff
                                  # needs less gain to read as the same strength)
    _VIGNETTE_SOFT_EDGE = 0.5    # falloff width; EllipseMask defaults to a hard 0 edge
    _VIGNETTE_WIDTH = 1.35       # ellipse half-width; default (~0.25) covers a tiny disc
    _VIGNETTE_HEIGHT = 1.35      # ellipse half-height
    _GRAIN_BLEND = 0.06         # grain opacity
    _LETTERBOX_CROP_RATIO = 0.06  # top+bottom crop fraction of frame height

    def _fusion_locked(comp, fn):
        """Run `fn()` inside its own Lock/Unlock cycle — the pattern every
        proven Fusion mutation in fusion_composition/actions.py uses
        (_safe_connect_fusion_tools, _safe_set_fusion_inputs)."""
        comp.Lock()
        try:
            return fn()
        finally:
            comp.Unlock()

    def _fusion_expression_set_ok(input_obj, expr, *, time=0):
        """Set `expr` on a Fusion Input and verify by read-back. SetExpression's
        own return is NOT trustworthy — fusion_composition/actions.py's
        _fusion_comp_bulk_set_expressions (the proven, live-verified path)
        discards it entirely and treats "no exception" as success; the live
        finding here confirms why: every SetExpression call in this function
        returned False even when creation, rename, wiring, AND expression were
        all applied within one unbroken Lock cycle. GetExpression readback is
        the real check (matches the repo's #113 Tier 3 doctrine)."""
        input_obj.SetExpression(str(expr), time)
        try:
            return bool(input_obj.GetExpression(time))
        except Exception:
            return False

    def _fusion_input_set_ok(tool, input_name, value, *, tol=1e-3):
        """Set `value` on a Fusion tool input and verify by read-back —
        SetInput's own return is not trustworthy, same doctrine as
        _fusion_expression_set_ok."""
        tool.SetInput(input_name, value)
        try:
            readback = tool.GetInput(input_name)
        except Exception:
            return False
        if readback is None:
            return False
        try:
            return abs(float(readback) - float(value)) <= tol
        except (TypeError, ValueError):
            return readback == value

    def _fusion_point_input_set_ok(tool, input_name, xy):
        """Set a Fusion Point input (e.g. a mask Center) and verify by read-back.
        Point inputs don't accept a plain scalar; the fusionscript bridge accepts
        a 2-element list or a 1-indexed table depending on platform/version, so
        try both encodings (matches fusion_composition/actions.py's
        _fusion_set_point_input)."""
        x, y = xy
        for cand in ([x, y], {1: x, 2: y}, {"1": x, "2": y}):
            try:
                tool.SetInput(input_name, cand)
            except Exception:
                continue
            try:
                readback = tool.GetInput(input_name)
            except Exception:
                readback = None
            if readback is None:
                continue
            try:
                rx, ry = readback[1], readback[2]
            except (KeyError, TypeError, IndexError):
                try:
                    rx, ry = readback[0], readback[1]
                except (KeyError, TypeError, IndexError):
                    continue
            if abs(float(rx) - float(x)) <= 1e-3 and abs(float(ry) - float(y)) <= 1e-3:
                return True
        return False

    def _ensure_fusion_tool_locked(comp, tool_type, name):
        """Find-or-create `name`. MUST be called from inside an ALREADY-OPEN
        comp.Lock() cycle (see _fusion_locked) — live finding: even AddTool
        immediately followed by SetAttrs(TOOLS_Name) in the SAME Lock/Unlock
        cycle (matching fusion_composition/actions.py's _safe_add_fusion_tool,
        position (-1, -1)) still leaves every LATER call on that tool
        (ConnectInput/SetExpression/SetInput) returning False once the lock
        is released and reacquired — even back-to-back with no other work in
        between. The only recipe that held up live end-to-end is doing
        creation AND all of a tool's wiring/expression calls inside ONE
        unbroken Lock/Unlock cycle. Returns (tool, tool_warning)."""
        tool = comp.FindTool(name)
        if tool:
            return tool, None
        try:
            tool = comp.AddTool(tool_type, -1, -1)
        except Exception as exc:
            return None, f"AddTool({tool_type}) failed: {type(exc).__name__}: {exc}"
        if not tool:
            return None, f"AddTool({tool_type}) returned no tool"
        try:
            tool.SetAttrs({"TOOLS_Name": name})
            renamed = tool.GetAttrs().get("TOOLS_Name") == name
        except Exception as exc:
            renamed = False
        if not renamed:
            # Not fatal — the tool is usable unnamed — but comp.FindTool(name)
            # won't find it next time, which would add a DUPLICATE tool on a
            # later finish() call against the same comp. Surface it rather
            # than silently reporting success (#111 finding 5/6's shape).
            return tool, f"AddTool({tool_type}) succeeded but SetAttrs(TOOLS_Name) failed"
        return tool, None

    def _apply_montage_motion(tl, plan, *, title_offset, look=True):
        """Issue #180, phase 5/6 of the montage-quality epic: beat-locked
        Fusion motion (a zoom ramp + a decaying pulse locked to the master
        beat grid, see montage_motion.build_zoom_expression), flash frames on
        section-opening downbeats, a rotational shake on the drop/high
        sections, a fade to black on the outro's last shot, speed ramps on
        flagged shots, and a vignette/grain look pass (``look``, on by default
        — see the module's adjustment-layer note above for why this is
        per-clip, not per-track).

        Motion/flash/shake/fadeout/look live on a small per-clip Fusion comp
        (MediaIn1 -> [BeatPulse Transform] -> [Flash BrightnessContrast] ->
        [Vignette] -> [Grain Merge] -> [Fadeout BrightnessContrast] ->
        MediaOut1) — non-destructive, GPU-accelerated, adjustable afterward in
        the Fusion page. Shake rides the BeatPulse Transform's Angle rather
        than adding a node; fadeout is deliberately LAST so grain does not
        sparkle over the black. Retime and letterbox are applied via existing
        per-item SetProperty calls (RetimeProcess / CropTop+CropBottom) — no
        Fusion node needed for either. Retime's process is set EXPLICITLY
        (never left at the project default); the speed ramp itself is authored
        by polish_timeline's retime_clip op, which the scripting API cannot do.
        """
        nonlocal montage_map_stats
        segments = plan.get("segments") or []
        fps = float(plan.get("fps") or 24.0)
        items = tl.GetItemListInTrack("video", 1) or []
        motion_applied = 0
        flash_applied = 0
        shake_applied = 0
        fadeout_applied = 0
        retime_applied = 0
        look_applied = 0
        letterbox_applied = 0
        errors: List[str] = []
        # Denominators are what the PLAN asked for, not what the mapper
        # matched — a segment the mapper couldn't find an item for still
        # counts toward "planned" (issue #203). Flags on unmatched segments
        # are tallied separately below for the shortfall warning.
        planned_motion = sum(1 for seg in segments if seg.get("motion"))
        planned_flash = sum(1 for seg in segments if seg.get("flash"))
        planned_shake = sum(1 for seg in segments if seg.get("shake") and seg.get("motion"))
        planned_fadeout = sum(1 for seg in segments if seg.get("fadeout"))
        planned_retime = sum(1 for seg in segments if seg.get("retime"))
        planned_look = len(segments) if look else 0

        pairs, montage_map_stats = _map_montage_items_to_segments(
            items, segments, title_offset, record_offset=title_offset)
        for item, seg_idx, seg in pairs:
            motion = seg.get("motion")
            flash = bool(seg.get("flash"))
            retime = bool(seg.get("retime"))
            # Shake rides the beat-pulse Transform, so it needs the same beat
            # directive motion does — in fallback (no grid) mode there is no
            # beat to lock a jitter to. Fadeout is anchored to the clip's own
            # tail, so it stands alone.
            shake = bool(seg.get("shake")) and bool(motion)
            fadeout = bool(seg.get("fadeout"))
            if not motion and not flash and not retime and not fadeout and not look:
                continue

            comp = None
            if motion or flash or fadeout or look:
                try:
                    comp_count = int(item.GetFusionCompCount() or 0)
                    comp = item.GetFusionCompByIndex(1) if comp_count >= 1 else item.AddFusionComp()
                except Exception as exc:
                    errors.append(f"segment {seg_idx}: Fusion comp setup failed: {type(exc).__name__}: {exc}")
                    comp = None

            upstream_name = "MediaIn1"
            comp_undo_started = False
            if comp is not None:
                # Groups this item's edits into one undo step. Deliberately
                # NOT held locked for the whole item — a single Lock/Unlock
                # cycle spanning AddTool through a later SetExpression on the
                # SAME tool still returned False live (Studio 21.0.2.4); only
                # per-mutation Lock/Unlock cycles (see _fusion_locked) took
                # effect, matching fusion_composition/actions.py's copy_tool.
                try:
                    comp.StartUndo(f"MCP montage motion segment {seg_idx}")
                    comp_undo_started = True
                except Exception:
                    comp_undo_started = False
            try:
                if motion and comp:
                    def _do_transform():
                        transform, tool_warning = _ensure_fusion_tool_locked(
                            comp, "Transform", _MOTION_TRANSFORM_TOOL)
                        if tool_warning:
                            errors.append(f"segment {seg_idx}: {tool_warning}")
                        if transform is None:
                            return None
                        media_in = comp.FindTool("MediaIn1")
                        media_out = comp.FindTool("MediaOut1")
                        if media_in:
                            transform.ConnectInput("Input", media_in)
                        if media_out:
                            media_out.ConnectInput("Input", transform)
                        record_len = _auto_edit_mod.cut_ir.segment_record_length(seg)
                        expr = _montage_motion_mod.build_zoom_expression(
                            zoom_start=motion["zoom_start"], zoom_end=motion["zoom_end"],
                            amp=motion["amp"], beat_seconds=motion["beat_seconds"], fps=fps,
                            clip_length_frames=record_len,
                        )
                        # SetExpression's `time` argument matches the
                        # existing, live-verified fusion_comp.bulk_set_expressions
                        # convention (op.get("time", 0)) — never call it with
                        # only the expression string.
                        return _fusion_expression_set_ok(transform["Size"], expr, time=0)
                    try:
                        ok = _fusion_locked(comp, _do_transform)
                        if ok:
                            motion_applied += 1
                            upstream_name = _MOTION_TRANSFORM_TOOL
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: SetExpression(Size) readback empty after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: motion expression failed: {type(exc).__name__}: {exc}")

                if shake and comp:
                    # Separate lock cycle from _do_transform deliberately: a
                    # single Lock/Unlock spanning two mutations of the SAME tool
                    # returned False live (see the note above _do_transform).
                    def _do_shake():
                        transform = comp.FindTool(_MOTION_TRANSFORM_TOOL)
                        if transform is None:
                            return None
                        shake_expr = _montage_motion_mod.build_shake_expression(
                            beat_seconds=motion["beat_seconds"], fps=fps,
                        )
                        return _fusion_expression_set_ok(transform["Angle"], shake_expr, time=0)
                    try:
                        ok = _fusion_locked(comp, _do_shake)
                        if ok:
                            shake_applied += 1
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: SetExpression(Angle) readback empty after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: shake expression failed: {type(exc).__name__}: {exc}")

                if flash and comp:
                    def _do_flash():
                        flash_tool, tool_warning = _ensure_fusion_tool_locked(
                            comp, "BrightnessContrast", _MOTION_FLASH_TOOL)
                        if tool_warning:
                            errors.append(f"segment {seg_idx}: {tool_warning}")
                        if flash_tool is None:
                            return None
                        upstream = comp.FindTool(upstream_name) or comp.FindTool("MediaIn1")
                        media_out = comp.FindTool("MediaOut1")
                        if upstream:
                            flash_tool.ConnectInput("Input", upstream)
                        if media_out:
                            media_out.ConnectInput("Input", flash_tool)
                        flash_expr = _montage_motion_mod.build_flash_expression()
                        return _fusion_expression_set_ok(flash_tool["Gain"], flash_expr, time=0)
                    try:
                        ok = _fusion_locked(comp, _do_flash)
                        if ok:
                            flash_applied += 1
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: SetExpression(Gain) readback empty after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: flash expression failed: {type(exc).__name__}: {exc}")

                if look and comp:
                    def _do_vignette():
                        mask, mask_warning = _ensure_fusion_tool_locked(comp, "EllipseMask", _VIGNETTE_MASK_TOOL)
                        vignette, vignette_warning = _ensure_fusion_tool_locked(
                            comp, "BrightnessContrast", _VIGNETTE_TOOL)
                        for w in (mask_warning, vignette_warning):
                            if w:
                                errors.append(f"segment {seg_idx}: {w}")
                        if mask is None or vignette is None:
                            return None
                        upstream = comp.FindTool(upstream_name) or comp.FindTool("MediaIn1")
                        media_out = comp.FindTool("MediaOut1")
                        if upstream:
                            vignette.ConnectInput("Input", upstream)
                        vignette.ConnectInput("EffectMask", mask)
                        if media_out:
                            media_out.ConnectInput("Input", vignette)
                        # EllipseMask defaults to a small ellipse with SoftEdge=0 (a
                        # hard-edged matte, not a vignette) — issue #201. Set the
                        # geometry explicitly so the mask reads as a soft falloff
                        # covering most of frame, verified by readback like every
                        # other input in this function.
                        mask_ok = (
                            _fusion_input_set_ok(mask, "SoftEdge", _VIGNETTE_SOFT_EDGE)
                            and _fusion_input_set_ok(mask, "Width", _VIGNETTE_WIDTH)
                            and _fusion_input_set_ok(mask, "Height", _VIGNETTE_HEIGHT)
                        )
                        if not mask_ok:
                            errors.append(
                                f"segment {seg_idx}: vignette mask geometry "
                                "SetInput readback mismatch"
                            )
                        center_ok = _fusion_point_input_set_ok(mask, "Center", (0.5, 0.5))
                        if not center_ok:
                            errors.append(f"segment {seg_idx}: vignette mask Center SetInput failed")
                        return (mask_ok and center_ok
                                and _fusion_input_set_ok(vignette, "ApplyMaskInverted", 1)
                                and _fusion_input_set_ok(vignette, "Gain", _VIGNETTE_GAIN))
                    try:
                        ok = _fusion_locked(comp, _do_vignette)
                        if ok:
                            upstream_name = _VIGNETTE_TOOL
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: vignette SetInput readback mismatch after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: vignette setup failed: {type(exc).__name__}: {exc}")

                    def _do_grain():
                        noise, noise_warning = _ensure_fusion_tool_locked(comp, "FastNoise", _GRAIN_NOISE_TOOL)
                        grain_merge, merge_warning = _ensure_fusion_tool_locked(comp, "Merge", _GRAIN_MERGE_TOOL)
                        for w in (noise_warning, merge_warning):
                            if w:
                                errors.append(f"segment {seg_idx}: {w}")
                        if noise is None or grain_merge is None:
                            return None
                        upstream = comp.FindTool(upstream_name) or comp.FindTool("MediaIn1")
                        media_out = comp.FindTool("MediaOut1")
                        if upstream:
                            grain_merge.ConnectInput("Background", upstream)
                        grain_merge.ConnectInput("Foreground", noise)
                        if media_out:
                            media_out.ConnectInput("Input", grain_merge)
                        return _fusion_input_set_ok(grain_merge, "Blend", _GRAIN_BLEND)
                    try:
                        ok = _fusion_locked(comp, _do_grain)
                        if ok:
                            look_applied += 1
                            upstream_name = _GRAIN_MERGE_TOOL
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: grain SetInput(Blend) readback mismatch after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: grain setup failed: {type(exc).__name__}: {exc}")

                    try:
                        top_ok = bool(item.SetProperty("CropTop", _LETTERBOX_CROP_RATIO))
                        bottom_ok = bool(item.SetProperty("CropBottom", _LETTERBOX_CROP_RATIO))
                        if top_ok and bottom_ok:
                            letterbox_applied += 1
                        else:
                            errors.append(f"segment {seg_idx}: SetProperty(CropTop/CropBottom) returned False")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: letterbox crop failed: {type(exc).__name__}: {exc}")

                if fadeout and comp:
                    # LAST in the chain, and on its OWN BrightnessContrast —
                    # never MCP_Flash's. Last, because a fade to black has to
                    # come after grain, or the grain keeps sparkling over the
                    # black. Its own tool, because the final outro entry can
                    # carry `flash` and `fadeout` at once (a one-entry outro
                    # section opens and closes on the same shot) and the two
                    # would otherwise fight over one Gain input.
                    def _do_fadeout():
                        fade_tool, tool_warning = _ensure_fusion_tool_locked(
                            comp, "BrightnessContrast", _MOTION_FADEOUT_TOOL)
                        if tool_warning:
                            errors.append(f"segment {seg_idx}: {tool_warning}")
                        if fade_tool is None:
                            return None
                        upstream = comp.FindTool(upstream_name) or comp.FindTool("MediaIn1")
                        media_out = comp.FindTool("MediaOut1")
                        if upstream:
                            fade_tool.ConnectInput("Input", upstream)
                        if media_out:
                            media_out.ConnectInput("Input", fade_tool)
                        record_len = _auto_edit_mod.cut_ir.segment_record_length(seg)
                        fade_expr = _montage_motion_mod.build_fadeout_expression(
                            fps=fps, clip_length_frames=record_len)
                        return _fusion_expression_set_ok(fade_tool["Gain"], fade_expr, time=0)
                    try:
                        ok = _fusion_locked(comp, _do_fadeout)
                        if ok:
                            fadeout_applied += 1
                            upstream_name = _MOTION_FADEOUT_TOOL
                        elif ok is False:
                            errors.append(f"segment {seg_idx}: SetExpression(Gain) readback empty after set")
                    except Exception as exc:
                        errors.append(f"segment {seg_idx}: fadeout expression failed: {type(exc).__name__}: {exc}")
            finally:
                if comp_undo_started:
                    try:
                        comp.EndUndo(True)
                    except Exception:
                        pass

            if retime:
                try:
                    if bool(item.SetProperty("RetimeProcess", _RETIME_PROCESS_MAP["optical_flow"])):
                        retime_applied += 1
                    else:
                        errors.append(f"segment {seg_idx}: SetProperty(RetimeProcess) returned False")
                except Exception as exc:
                    errors.append(f"segment {seg_idx}: retime failed: {type(exc).__name__}: {exc}")

        result = {
            # `of` is the count of PLANNED segments carrying this flag — not
            # the count of segments the mapper actually found an item for
            # (issue #203). A segment the mapper couldn't match still counts
            # here, so e.g. fadeout: {applied: 0, of: 1} is distinguishable
            # from a plan that simply had no fadeout at all.
            "motion": {"applied": motion_applied, "of": planned_motion},
            "flash": {"applied": flash_applied, "of": planned_flash},
            "shake": {"applied": shake_applied, "of": planned_shake},
            "fadeout": {"applied": fadeout_applied, "of": planned_fadeout},
            "look": {"applied": look_applied, "of": planned_look,
                     "letterbox_applied": letterbox_applied, "letterbox_of": planned_look,
                     "note": "per-clip vignette/grain/letterbox — InsertGeneratorIntoTimeline "
                             "track targeting is unreliable (verified live), see module note"},
            "retime": {"applied": retime_applied, "of": planned_retime, "process": "optical_flow"},
        }
        if errors:
            result["errors"] = errors
        return result

    if action == "finish":
        _r, proj, project_root, err = _auto_edit_project_context(p, need_resolve=True)
        if err:
            return err
        gate = _auto_edit_mod.require_approved_plan(project_root, _plan_id_param())
        if not gate.get("success"):
            return _err(gate.get("error") or "plan gate failed")
        plan = gate["plan"]
        exec_summary = plan.get("execution_summary") or {}
        built_name = exec_summary.get("timeline_name")
        if not built_name:
            return _err("plan has no built timeline yet — build_timeline first")
        # target: which timeline this grades and renders. Default stays "built"
        # — polish_timeline deliberately leaves the built one intact. But the
        # polish round-trip is the ONLY place transitions and speed ramps can be
        # authored (no scripting API for either), so without this selector that
        # work could never reach a render.
        target = str(p.get("target") or "built").strip().lower()
        if target not in ("built", "polished"):
            return _err(f"target must be 'built' or 'polished' (got {target!r})")
        if target == "polished":
            polished_name = (exec_summary.get("polished") or {}).get("timeline_name")
            if not polished_name:
                return _err("plan has no polished timeline yet — polish_timeline first, "
                            "or call finish without target= to use the built one")
            built_name = polished_name
        tl, _idx = _find_timeline_by_name(proj, built_name)
        if not tl:
            return _err(f"{target} timeline {built_name!r} not found in the project")
        grade = p.get("grade") if isinstance(p.get("grade"), dict) else None
        subtitles = p.get("subtitles") if isinstance(p.get("subtitles"), dict) else None
        render = p.get("render") if isinstance(p.get("render"), dict) else None
        motion_opts = p.get("motion") if isinstance(p.get("motion"), dict) else None
        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            return _issue_confirm_token(
                action="auto_edit.finish", params=p,
                preview={
                    "operation": "auto_edit.finish",
                    "warning": f"Applies grade/subtitles to the {target} timeline and "
                               "renders an output file.",
                    "timeline": built_name,
                    "target": target,
                    "grade": {k: v for k, v in (grade or {}).items() if k != "cdl"},
                    "subtitles": bool(subtitles),
                    "motion": bool(motion_opts),
                    "render_target": (render or {}).get("target_dir"),
                },
            )
        blocked = _consume_confirm_token(action="auto_edit.finish", params=p)
        if blocked:
            return blocked
        # #113 Tier 1: finish grades/subtitles/renders the current timeline. A
        # failed switch would grade and render the wrong one — and this step is
        # past the confirm-token gate, so it runs unattended.
        if not _set_current_timeline(proj, tl):
            return _err(f"Could not make timeline '{built_name}' current; refusing to "
                        "grade/render, which would target the wrong timeline")
        result: Dict[str, Any] = {"success": True, "timeline": built_name, "target": target}
        # Set by grade.match and/or the motion pass below when either maps
        # V1 items back to plan segments — whichever ran last wins, but both
        # read the same items/segments/title_offset so they agree when both
        # run (issue #203's evidence: grade + motion in the same finish call).
        montage_map_stats: Optional[Dict[str, Any]] = None

        if grade:
            graded: Dict[str, Any] = {}
            items = tl.GetItemListInTrack("video", 1) or []
            if grade.get("match"):
                # Per-bucket "match" CDL (issue #179, phase 4/6 of the
                # montage-quality epic) — stage 1 of a two-stage grade. Maps
                # each V1 item back to its plan segment (item order mirrors
                # segment order, offset by the intro title's record_offset —
                # build_timeline records it in execution_summary.title) and
                # applies THAT segment's bucket's CDL, so lighting conditions
                # that can't intercut under one uniform CDL actually match.
                # Only `lut_path` genuinely composes on top of this (#193
                # phase 2.2). SetLUT is a separate node control, so a uniform
                # LUT rides over the per-bucket CDLs as intended. A uniform
                # `cdl`, though, is item.SetCDL on the SAME items — it
                # OVERWRITES every match CDL set here — and `drx_path` is a
                # whole-graph replace. This comment used to claim all three
                # were additive, and finish() still reported match.applied N/N
                # from this loop afterwards, so a host could declare a shot
                # match that no longer existed. The destructive combinations
                # are now reported in graded["match"]["overwritten_by"].
                match_map = grade["match"] if isinstance(grade["match"], dict) else {}
                segments = plan.get("segments") or []
                title_offset = int(
                    ((plan.get("execution_summary") or {}).get("title") or {}).get("record_offset") or 0)
                ok_count = 0
                by_bucket: Dict[str, int] = {}
                match_errors = []
                # Same mapping as the motion stage — record-frame based, so a
                # polished timeline's cross-dissolve items don't shift every
                # shot after the first dissolve onto the wrong bucket (#193
                # phase 6.2.5). This loop used to walk positions inline.
                pairs, montage_map_stats = _map_montage_items_to_segments(
                    items, segments, title_offset, record_offset=title_offset)
                for item, _seg_idx, seg in pairs:
                    bucket = seg.get("look_bucket")
                    bucket_grade = match_map.get(bucket) if bucket else None
                    if not isinstance(bucket_grade, dict):
                        continue
                    # Accept BOTH the documented {bucket: {"cdl": …}} wrapper and
                    # the RAW {bucket: <CDL>} shape the plan's own look_buckets
                    # hands back (montage_edit.compute_match_cdls). Feeding this
                    # tool its own suggestion is the obvious call, and requiring
                    # the re-wrap made that a SILENT no-op — applied: 0, no error.
                    cdl = bucket_grade.get("cdl")
                    if cdl is None and "Slope" in bucket_grade:
                        cdl = bucket_grade
                    if not cdl:
                        continue
                    try:
                        if item.SetCDL(_normalize_cdl(cdl)):
                            ok_count += 1
                            by_bucket[bucket] = by_bucket.get(bucket, 0) + 1
                    except Exception as exc:
                        match_errors.append(f"{type(exc).__name__}: {exc}")
                # `of` is the PLANNED segment count, not len(items) — a
                # polished timeline can have fewer V1 items than the plan has
                # segments (issue #203), and len(items) silently absorbed that
                # shortfall into a denominator that then read as "complete."
                graded["match"] = {"applied": ok_count, "of": len(segments), "by_bucket": by_bucket}
                if montage_map_stats["unmatched_segment_indices"]:
                    graded["match"]["unmatched_segments"] = montage_map_stats["unmatched_segment_indices"]
                # Report the destructive combinations rather than letting the
                # host read `applied: N/N` and believe the match survived
                # (#193 phase 2.2). Named here, at the moment they are known.
                overwritten_by = [
                    key for key in ("cdl", "drx_path") if grade.get(key)]
                if overwritten_by:
                    graded["match"]["overwritten_by"] = overwritten_by
                    graded["match"]["warning"] = (
                        "the per-bucket match CDLs reported above were REPLACED by the "
                        f"uniform {' and '.join(overwritten_by)} applied after them — "
                        "`cdl` is item.SetCDL on the same items and `drx_path` replaces "
                        "the whole node graph. Only `lut_path` composes with `match`; use "
                        "it (or drx_path INSTEAD of match) if the shot match should survive.")
                if match_errors:
                    graded["match_error"] = "; ".join(sorted(set(match_errors)))
            if grade.get("lut_path"):
                ok_count = 0
                for item in items:
                    try:
                        g = item.GetNodeGraph()
                        if g and g.SetLUT(int(grade.get("node_index") or 1), str(grade["lut_path"])):
                            ok_count += 1
                    except Exception:
                        continue
                graded["lut"] = {"applied": ok_count, "of": len(items)}
            if grade.get("cdl"):
                normalized = _normalize_cdl(grade["cdl"])
                ok_count = 0
                for item in items:
                    try:
                        if item.SetCDL(normalized):
                            ok_count += 1
                    except Exception:
                        continue
                graded["cdl"] = {"applied": ok_count, "of": len(items)}
            if grade.get("drx_path"):
                # ApplyGradeFromDRX(path, gradeMode) is a GRAPH method, and
                # Timeline.ApplyGradeFromDRX is fabricated - live-verified absent
                # from dir(Timeline) on 21.0.2.4. The old call passed three
                # arguments to it on the timeline, so the swallowed
                # "TypeError: 'NoneType' object is not callable" made every
                # auto-edit finish carrying a drx_path report
                # {"drx": {"applied": false}} with the cause buried in drx_error:
                # the .drx grade has never been applied by this path (#144
                # finding 5). Apply per item on its own node graph, guarded, the
                # way granular/graph.py and color_grade/actions.py already do.
                drx_path = str(grade["drx_path"])
                grade_mode = int(grade.get("grade_mode") or 0)
                ok_count = 0
                drx_errors = []
                for item in items:
                    try:
                        g = item.GetNodeGraph()
                    except Exception as exc:
                        drx_errors.append(f"GetNodeGraph: {type(exc).__name__}: {exc}")
                        continue
                    if not _has_method(g, "ApplyGradeFromDRX"):
                        drx_errors.append("node graph does not expose ApplyGradeFromDRX")
                        continue
                    try:
                        if g.ApplyGradeFromDRX(drx_path, grade_mode):
                            ok_count += 1
                    except Exception as exc:
                        drx_errors.append(f"{type(exc).__name__}: {exc}")
                graded["drx"] = {"applied": ok_count, "of": len(items)}
                if drx_errors:
                    # Deduplicate: one identical message per item is noise.
                    graded["drx_error"] = "; ".join(sorted(set(drx_errors)))
            result["grade"] = graded

        if motion_opts is not None:
            title_offset = int(((plan.get("execution_summary") or {}).get("title") or {}).get("record_offset") or 0)
            result.update(_apply_montage_motion(
                tl, plan, title_offset=title_offset, look=bool(motion_opts.get("look", True))))

        # Top-level shortfall warning (issue #203): grade.match and/or the
        # motion pass above set montage_map_stats when either mapped V1 items
        # back to plan segments. Compose ONE warning naming exactly which
        # flags were lost on the unmatched segments, rather than making a
        # host diff per-field `applied`/`of` counts by hand to notice.
        if montage_map_stats and montage_map_stats["unmatched_segment_indices"]:
            unmatched_idxs = montage_map_stats["unmatched_segment_indices"]
            segments_for_warning = plan.get("segments") or []
            lost_counts = {
                "motion": sum(1 for i in unmatched_idxs if segments_for_warning[i].get("motion")),
                "flash": sum(1 for i in unmatched_idxs if segments_for_warning[i].get("flash")),
                "fadeout": sum(1 for i in unmatched_idxs if segments_for_warning[i].get("fadeout")),
                "retime": sum(1 for i in unmatched_idxs if segments_for_warning[i].get("retime")),
            }
            lost_desc = ", ".join(
                f"{n} {flag}" for flag, n in lost_counts.items() if n) or "no flagged directives"
            result["warning"] = (
                f"{len(unmatched_idxs)} plan segment(s) had no matching timeline item on "
                f"{built_name!r} — {lost_desc} not applied. The {target} timeline has "
                f"{montage_map_stats['item_count']} V1 items for "
                f"{montage_map_stats['planned_segments']} plan segments.")

        if subtitles:
            result["subtitles"] = _safe_create_subtitles(tl, subtitles)

        if render:
            target_dir = str(render.get("target_dir") or render.get("targetDir") or "")
            if not target_dir:
                from src.domains.media_analysis.utils import analysis_memory as _analysis_memory
                target_dir = os.path.join(
                    _analysis_memory.memory_dir(project_root), "auto_edit", "renders")
            os.makedirs(target_dir, exist_ok=True)
            custom_name = str(render.get("custom_name") or render.get("customName")
                              or f"auto_edit_{plan['plan_id']}")
            render_settings = dict(render.get("settings") or {})
            # For a music-cut montage the audio IS the deliverable, and
            # ExportAudio is PROJECT-WIDE sticky state: render(build_proxies)
            # writes ExportAudio=False (deliberately — it dodges the headless
            # Fairlight/PipeWire 0%-stall) and never restores it, so a proxy
            # build earlier in the same session left the next montage render
            # silent with every check green (#193 phase 5.4). Assert it here
            # rather than inheriting whatever the project happens to hold. An
            # explicit caller setting still wins.
            if _is_montage_plan(plan):
                render_settings.setdefault("ExportAudio", True)
            prepared = _prepare_render_job(proj, {
                "target_dir": target_dir,
                "settings": render_settings,
                "format": render.get("format"),
                "codec": render.get("codec"),
                "custom_name": custom_name,
                "require_temp_target": False,
            })
            if not prepared.get("success"):
                result["success"] = False
                result["render"] = prepared
                return result
            job_id = prepared["job_id"]

            def _render_work():
                render_started = time.time()
                started = bool(proj.StartRendering([job_id], False))
                if not started:
                    return {"success": False, "error": "StartRendering returned false", "job_id": job_id}
                while proj.IsRenderingInProgress():
                    time.sleep(2)
                status = _ser(proj.GetRenderJobStatus(job_id))
                job_failed = str((status or {}).get("JobStatus") if isinstance(status, dict)
                                 else "").lower() in ("failed", "cancelled", "canceled")
                # Only files written by THIS render count — a prior finish of
                # the same plan leaves same-prefix files behind (2s tolerance
                # for coarse filesystem mtimes).
                outputs = []
                for fname in os.listdir(target_dir):
                    if not fname.startswith(custom_name):
                        continue
                    full = os.path.join(target_dir, fname)
                    if os.path.getmtime(full) >= render_started - 2:
                        outputs.append(full)
                outputs.sort(key=os.path.getmtime, reverse=True)
                output_path = outputs[0] if outputs else None
                out = {
                    "success": bool(output_path and os.path.isfile(output_path)) and not job_failed,
                    "job_id": job_id,
                    "status": status,
                    "output_path": output_path,
                }
                if not output_path:
                    out["error"] = "no output file found after render"
                elif job_failed:
                    out["error"] = "render job did not complete"
                return out

            # auto_edit is async, so the inline (non-background) render path —
            # a poll loop that lasts the whole render — must not run on the
            # event loop; every concurrent MCP request would stall until done.
            import anyio
            render_result = await anyio.to_thread.run_sync(
                lambda: _run_maybe_background("auto_edit.finish_render", p, _render_work))
            result["render"] = render_result
            if isinstance(render_result, dict) and render_result.get("success") is False:
                result["success"] = False

            # Visual QC pass (issue #181, phase 6/6 of the montage-quality
            # epic): on by default for montage, matching phase 3's scouting
            # posture. Purely additive to the render result — a failure or
            # decline here never flips result["success"]; the mechanical
            # beat-alignment readback (build_timeline) already ran regardless.
            qc_opts = p.get("qc")
            qc_enabled = not (
                qc_opts is False or (isinstance(qc_opts, dict) and qc_opts.get("enabled") is False))
            if (qc_enabled and _is_montage_plan(plan) and isinstance(render_result, dict)
                    and render_result.get("success") and render_result.get("output_path")):
                result["qc"] = _montage_edit_mod.build_qc_request(
                    plan, render_result["output_path"], project_root)
        if result["success"] and plan.get("brief_id"):
            _auto_edit_mod.advance_brief(project_root, plan["brief_id"], "finished")
        return result

    if action == "polish_timeline":
        # Phase-2 pro polish: the append-rebuild scripting API cannot author
        # transitions or place titles on upper tracks, so export the built
        # timeline as .drt (the only lossless project-native round-trip), run
        # verified drp-format vendor ops on it in scratch, and reimport as a
        # NEW "(polished)" timeline. Export-then-modify preserves the media-link
        # blobs byte-for-byte, so media stays linked without a relink pass.
        _r, proj, project_root, err = _auto_edit_project_context(p, need_resolve=True)
        if err:
            return err
        gate = _auto_edit_mod.require_approved_plan(project_root, _plan_id_param())
        if not gate.get("success"):
            return _err(gate.get("error") or "plan gate failed")
        plan = gate["plan"]
        exec_summary = plan.get("execution_summary") or {}
        built_name = exec_summary.get("timeline_name")
        if not built_name:
            return _err("plan has no built timeline yet — build_timeline first")
        tl, _idx = _find_timeline_by_name(proj, built_name)
        if not tl:
            return _err(f"built timeline {built_name!r} not found in the project")

        # Decide the ops offline (pure). An exported .drt encodes ABSOLUTE frame
        # positions — the timeline's start frame (01:00:00:00 → 86400 @ 24fps) is
        # baked into every clip's Start (verified live on Resolve Studio 21). So op
        # positions = timeline_start + build_timeline's intro-title footprint +
        # the plan's record frames. Passing only the title offset would place
        # dissolves near frame 0, outside the clips.
        timeline_start = int(_timeline_start_frame(tl) or 0)
        title_offset = int((exec_summary.get("title") or {}).get("record_offset") or 0)
        polish = _auto_edit_mod.plan_polish_ops(
            plan, record_offset=timeline_start + title_offset, options=p.get("options"))
        ops = polish.get("ops") or []
        if not ops:
            # Genre-aware remediation (#193 phase 2.8). Montage defaults to
            # no_dissolves — every montage cut is a source change, so the
            # talking-head heuristic would dissolve the whole edit — and it
            # never consults dissolve_on_beat_change at all. Naming that knob
            # to a montage host sent them somewhere with no effect. With
            # default options the only montage ops are speed ramps, which
            # exist only when the arrangement produced build/accelerate
            # sections, so an empty op set is the EXPECTED outcome here, not a
            # failure of the build.
            if _is_montage_plan(plan):
                return _err(
                    "nothing to polish on this montage — expected, not a build failure. "
                    "Montage defaults to no_dissolves (every montage cut is a source "
                    "change, so the talking-head heuristic would dissolve the whole "
                    "edit), and with default options its only ops are speed ramps, which "
                    "exist only when the arrangement produced `build`/`accelerate` "
                    "sections. To get dissolves anyway pass options={\"no_dissolves\": "
                    "false} — only a cut that OPENS a `breathe` section gets one. "
                    "polish_timeline is optional: finish() targets the BUILT timeline.",
                ) | {"polish": polish}
            return _err(
                "nothing to polish: no flagged cuts or lower-thirds for this cut "
                "(single-source cuts have no source-change dissolves; pass "
                "options.lower_thirds or options.dissolve_on_beat_change)",
            ) | {"polish": polish}

        # Honest refusal before touching Resolve: the surgery needs the Node
        # advanced-server bridge (drp-format vendor ops).
        if not _advanced_bridge.node_available():
            return _err(
                "polish requires the Node advanced-server bridge (drp-format), "
                "and Node.js was not found on PATH — install Node 18+ to enable it.",
            ) | {"polish": polish}

        if "confirm_token" not in p and "confirmToken" not in p and _confirm_token_required():
            return _issue_confirm_token(
                action="auto_edit.polish_timeline", params=p,
                preview={
                    "operation": "auto_edit.polish_timeline",
                    "warning": "Exports the built timeline as .drt, applies "
                               f"{polish['transitions']} cross-dissolve(s) and "
                               f"{polish['lower_thirds']} lower-third(s) via offline "
                               "drt surgery, and imports a NEW '(polished)' timeline. "
                               "No existing timeline is modified.",
                    "built_timeline": built_name,
                    "transitions": polish["transitions"],
                    "lower_thirds": polish["lower_thirds"],
                    "ops": [{"op": o["op"], "reason": o.get("reason")} for o in ops],
                    "notes": polish.get("notes"),
                },
            )
        blocked = _consume_confirm_token(action="auto_edit.polish_timeline", params=p)
        if blocked:
            return blocked

        # Baseline the built timeline's media coverage BEFORE the round-trip: it
        # already carries media-less generators (the intro title) that read as
        # "offline". The polished timeline is judged against this, not a raw count,
        # so those known generators don't false-alarm as dropped source clips.
        baseline_media = _timeline_media_coverage(tl)

        # Holds a full .drt export of the built timeline plus the op chain's
        # intermediates; removed on every exit (#143 finding 4).
        scratch = tempfile.mkdtemp(prefix="auto_edit_polish_")
        try:
            export_path = os.path.join(scratch, f"{plan['plan_id']}.drt")
            exported = _export_timeline_checked(tl, {
                "path": export_path, "format": "drt",
                "require_temp_path": False, "background": False, "async_job": False,
            })
            if not exported.get("success"):
                return _err("drt export failed — cannot polish") | {"export": exported}
            drt_src = exported.get("primary_file") or export_path

            chain = _advanced_bridge.run_drp_op_chain(
                ops, drt_src, scratch_dir=os.path.join(scratch, "ops"))
            if not chain.get("success"):
                return _err(chain.get("error") or "polish op chain failed") | {
                    "chain": chain, "polish": polish}
            polished_drt = chain["output_path"]

            mp = proj.GetMediaPool()
            if not mp:
                return _err("No media pool")
            polished_name = _unique_timeline_name(proj, f"{built_name} (polished)")
            imported = _import_timeline_checked(proj, mp, {
                "path": polished_drt, "timeline_name": polished_name,
                "require_temp_path": False,
            })
            if not imported.get("success"):
                return _err(imported.get("error") or "reimport of polished .drt failed") | {
                    "import": imported, "chain": chain}

            # Resolve names the imported timeline after the .drt container, ignoring the
            # timelineName import option (verified live on 21) — rename it explicitly so
            # the polished timeline reads as "<built> (polished)".
            final_name = imported.get("name") or polished_name
            imp_tl = None
            for _i in range(1, int(proj.GetTimelineCount() or 0) + 1):
                cand = proj.GetTimelineByIndex(_i)
                if cand and str(cand.GetUniqueId()) == str(imported.get("id")):
                    imp_tl = cand
                    break
            if imp_tl is not None:
                try:
                    if imp_tl.SetName(polished_name):
                        final_name = polished_name
                except Exception:
                    pass

            # NOTE (checked, intentional): ImportTimelineFromFile makes the polished
            # timeline Resolve's CURRENT one, same mechanism Stage 3.1 (#21) found
            # and restores-away for its trim/move/split/etc. actions. Deliberately
            # left as-is here: `finish` looks up the built timeline by NAME via the
            # plan and calls proj.SetCurrentTimeline(tl) itself before doing any
            # work (see the "finish" branch above), so it never depends on current-
            # timeline state either way — and the docstring's own next-step guidance
            # ("review the (polished) timeline") wants it front-and-center in the
            # Resolve UI right after this call, unlike the small composable Stage
            # 3.1 edits where switching the user's context away is a surprise.

            # Media-link honesty: the polish adds media-less items (a lower-third Text+
            # and, in the reimported timeline, a cross-dissolve transition item) that
            # all read as "offline", so an offline-count diff false-positives. The
            # robust signal is the LINKED count — a dropped source clip is the only
            # thing that reduces it (verified live on a two-source cut: built 9/8 linked
            # → polished 11/8 linked, offline +2, zero clips dropped). Diff linked
            # against the built timeline's pre-round-trip coverage.
            media = imported.get("media") or {}
            real_offline = _auto_edit_mod.dropped_source_clips(
                baseline_linked=int(baseline_media.get("linked", 0)),
                polished_linked=int(media.get("linked", 0)))

            # "went offline" vs "no longer present" (issue #202): the media-link
            # diff above cannot tell an item that's still on the track but lost
            # its Media Pool link apart from an item that's simply gone. V1's own
            # item COUNT can: it only drops when an item vanished outright.
            def _v1_item_count(timeline_obj):
                if timeline_obj is None:
                    return None
                try:
                    items = timeline_obj.GetItemListInTrack(
                        "video", _auto_edit_mod.SPEECH_VIDEO_TRACK) or []
                    return len(items)
                except Exception:
                    return None

            built_v1_count = _v1_item_count(tl)
            polished_v1_count = _v1_item_count(imp_tl)
            missing_items = (
                max(0, built_v1_count - polished_v1_count)
                if built_v1_count is not None and polished_v1_count is not None
                else None
            )

            # Gap check (issue #202 acceptance criteria): never ship a gap
            # silently. detect_gaps_overlaps already exists (timeline_edit) —
            # reuse it against the polished timeline's own snapshot.
            gaps_out: Optional[Dict[str, Any]] = None
            if imp_tl is not None:
                try:
                    from src.domains.timeline_conform_interchange.actions import (
                        _detect_gaps_overlaps_from_snapshot, _timeline_conform_snapshot)
                    snapshot = _timeline_conform_snapshot(imp_tl, {})
                    gaps_report = _detect_gaps_overlaps_from_snapshot(snapshot, {})
                    gaps_out = {
                        "count": gaps_report["gap_count"],
                        "frames": sum(g.get("duration", 0) for g in gaps_report["gaps"]),
                        "positions": gaps_report["gaps"],
                    }
                except Exception as exc:
                    gaps_out = {"error": f"gap check failed: {type(exc).__name__}: {exc}"}

            out = {
                "success": True,
                "polished_timeline": final_name,
                "source_timeline": built_name,
                "transitions": polish["transitions"],
                "lower_thirds": polish["lower_thirds"],
                "speed_ramps": polish["speed_ramps"],
                "ops_applied": len(ops),
                "media_link": media,  # {total, linked, offline}; offline includes added generators
                "baseline_media_link": baseline_media,  # built timeline before the round-trip
                "clips_relinked": real_offline == 0,
                "notes": polish.get("notes"),
                "plan_id": plan["plan_id"],
                "next": "review the (polished) timeline; finish(plan_id) grades/renders the "
                        "BUILT timeline by default — pass finish(target='polished') to "
                        "render this one instead",
            }
            if gaps_out is not None:
                out["gaps"] = gaps_out
            warnings: List[str] = []
            if missing_items:
                warnings.append(
                    f"{missing_items} item(s) present on the built timeline's V"
                    f"{_auto_edit_mod.SPEECH_VIDEO_TRACK} are no longer present on the "
                    f"polished timeline ({built_v1_count} -> {polished_v1_count}) — they "
                    "did not go offline, they are simply absent.")
            # A missing V1 item is also a linked-media drop, so don't double-report
            # the same loss under both messages.
            offline_only = max(0, real_offline - (missing_items or 0))
            if offline_only:
                warnings.append(
                    f"{offline_only} source clip(s) went offline after the drt round-trip "
                    "(beyond the intro title and added lower-thirds) — check media relinking.")
            if gaps_out and gaps_out.get("count"):
                warnings.append(
                    f"{gaps_out['count']} gap(s) totalling {gaps_out['frames']} frame(s) on "
                    "the polished timeline — these will render as black frames; see `gaps` "
                    "for positions.")
            if warnings:
                out["warning"] = " | ".join(warnings)
            _edit_engine_mod.mark_plan_executed(project_root, plan["plan_id"], {
                **exec_summary,
                "polished": {
                    "timeline_name": out["polished_timeline"],
                    "transitions": polish["transitions"],
                    "lower_thirds": polish["lower_thirds"],
                    "speed_ramps": polish["speed_ramps"],
                    "media_link": media,
                },
            })
            return out
        finally:
            shutil.rmtree(scratch, ignore_errors=True)

    if action == "commit_qc":
        # Finishes the visual QC pass's host-vision handoff (issue #181,
        # phase 6/6 of the montage-quality epic): the deferred payload from
        # finish()'s `qc` field asked the host to look at frames and return
        # findings; this normalizes them and, for one tied to a specific
        # cut, returns a suggested revise_cut edit. Read-only against the
        # plan (does not itself apply the edit) — no confirm-token needed.
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        plan = _edit_engine_mod.load_plan(project_root, _plan_id_param())
        if not plan:
            return _err(f"plan not found: {_plan_id_param()!r}")
        return _montage_edit_mod.commit_qc_report(plan, p.get("qc_report"))

    if action == "list_briefs":
        _r, _proj, project_root, err = _auto_edit_project_context(p, need_resolve=False)
        if err:
            return err
        rows = _edit_engine_mod.list_plans(project_root, limit=int(p.get("limit") or 50))
        briefs = [row for row in rows.get("plans") or []
                  if row.get("kind") == _auto_edit_mod.BRIEF_KIND]
        return {"success": True, "briefs": briefs}

    return _unknown(action, [
        "start_brief",
        "brief_status",
        "status",
        "plan_cut",
        "revise_cut",
        "get_cut_summary",
        "approve_cut",
        "build_timeline",
        "polish_timeline",
        "finish",
        "commit_qc",
        "list_briefs",
    ])


_STRATA_CLIP_REF_KEYS = (
    "clip_id", "clipId", "clip_uuid", "clipUuid",
    "clip_dir", "clipDir", "file_path", "filePath",
)
